screenPanels.initJs:
function(container, apiUrl, tables) {
  const loginForm = container.querySelector('#login-form');
  const dashboardView = container.querySelector('#dashboard-view');
  const errorMessage = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');

  // パスワード表示/非表示切り替え
  const passwordInput = container.querySelector('#password');
  const togglePasswordBtn = container.querySelector('#toggle-password');

  togglePasswordBtn.addEventListener('click', () => {
    const type = passwordInput.getAttribute('type') === 'password' ? 'text' : 'password';
    passwordInput.setAttribute('type', type);
    togglePasswordBtn.textContent = type === 'password' ? '👁️' : '🙈';
  });

  // エラーメッセージ表示関数
  function showError(message) {
    errorText.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // ログイン処理
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();

    const userId = container.querySelector('#user-id').value;
    const password = container.querySelector('#password').value;
    const rememberMe = container.querySelector('#remember-me').checked;

    if (!userId || !password) {
      showError('ユーザーIDとパスワードを入力してください');
      return;
    }

    try {
      // ユーザー認証（実際のAPIでは認証エンドポイントを使用）
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      const user = users.find(u => u.メールアドレス === userId && u.アクティブフラグ);

      if (!user) {
        showError('ユーザーIDまたはパスワードが正しくありません');
        return;
      }

      // ログイン成功
      if (rememberMe) {
        localStorage.setItem('rememberedUser', userId);
      }

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // ダッシュボード表示
      container.querySelector('.login-container').style.display = 'none';
      dashboardView.classList.remove('hidden');
      dashboardView.style.display = 'block';

      // ユーザー名表示
      container.querySelector('#user-name').textContent = `${user.ユーザー名} さん`;

      // KPI更新
      await updateKPIs();

      // グラフ描画
      await drawCharts();

    } catch (error) {
      showError('ログインに失敗しました。しばらく時間をおいて再度お試しください。');
    }
  });

  // KPI更新関数
  async function updateKPIs() {
    try {
      const applications = await window.aivicApi.list(1); // 申請書類テーブル
      const currentMonth = new Date().toISOString().slice(0, 7);

      // 今月の申請件数
      const monthlyApps = applications.filter(app => 
        app.作成日時 && app.作成日時.slice(0, 7) === currentMonth
      );
      container.querySelector('#kpi-monthly-applications').textContent = monthlyApps.length;

      // 承認待ち件数
      const pendingApps = applications.filter(app => 
        app.承認状態 === '申請中' || app.承認状態 === '承認待ち'
      );
      container.querySelector('#kpi-pending-approvals').textContent = pendingApps.length;

      // 今月の申請金額
      const monthlyAmount = monthlyApps.reduce((sum, app) => 
        sum + (app.申請金額 || 0), 0
      );
      container.querySelector('#kpi-monthly-amount').textContent = 
        `¥${monthlyAmount.toLocaleString()}`;

      // 平均承認日数（承認済みの案件から計算）
      const approvedApps = applications.filter(app => 
        app.承認状態 === '承認済' && app.最終承認日時 && app.作成日時
      );
      let avgDays = 0;
      if (approvedApps.length > 0) {
        const totalDays = approvedApps.reduce((sum, app) => {
          const created = new Date(app.作成日時);
          const approved = new Date(app.最終承認日時);
          return sum + Math.ceil((approved - created) / (1000 * 60 * 60 * 24));
        }, 0);
        avgDays = Math.round(totalDays / approvedApps.length);
      }
      container.querySelector('#kpi-avg-approval-days').textContent = `${avgDays}日`;

    } catch (error) {
      console.error('KPI更新エラー:', error);
    }
  }

  // グラフ描画関数
  async function drawCharts() {
    try {
      const applications = await window.aivicApi.list(1);

      // 月別申請件数グラフ
      const monthlyData = {};
      applications.forEach(app => {
        if (app.作成日時) {
          const month = app.作成日時.slice(0, 7);
          monthlyData[month] = (monthlyData[month] || 0) + 1;
        }
      });

      const months = Object.keys(monthlyData).sort().slice(-6);
      const counts = months.map(month => monthlyData[month] || 0);

      new window.Chart(container.querySelector('#monthly-chart'), {
        type: 'line',
        data: {
          labels: months.map(m => m.slice(5)),
          datasets: [{
            label: '申請件数',
            data: counts,
            borderColor: '#3b82f6',
            backgroundColor: 'rgba(59, 130, 246, 0.1)',
            tension: 0.4
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          scales: {
            y: {
              beginAtZero: true,
              ticks: { stepSize: 1 }
            }
          }
        }
      });

      // 申請種別分布グラフ
      const categoryData = {};
      applications.forEach(app => {
        if (app.申請種別) {
          categoryData[app.申請種別] = (categoryData[app.申請種別] || 0) + 1;
        }
      });

      const categories = Object.keys(categoryData);
      const categoryCounts = Object.values(categoryData);

      new window.Chart(container.querySelector('#category-chart'), {
        type: 'doughnut',
        data: {
          labels: categories,
          datasets: [{
            data: categoryCounts,
            backgroundColor: [
              '#3b82f6', '#ef4444', '#10b981', '#f59e0b', '#8b5cf6', '#06b6d4'
            ]
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false
        }
      });

    } catch (error) {
      console.error('グラフ描画エラー:', error);
    }
  }

  // メニューボタンのイベントリスナー
  container.querySelector('#btn-new-application').addEventListener('click', () => {
    window.showScreen("scr-1779422326698");
  });

  container.querySelector('#btn-document-registration').addEventListener('click', () => {
    window.showScreen("scr-1779422207222");
  });

  container.querySelector('#btn-progress-management').addEventListener('click', () => {
    window.showScreen("scr-1779422241190");
  });

  container.querySelector('#btn-approval-tasks').addEventListener('click', () => {
    window.showScreen("scr-1779422407913");
  });

  container.querySelector('#btn-history-inquiry').addEventListener('click', () => {
    window.showScreen("scr-1779422306272");
  });

  container.querySelector('#btn-document-search').addEventListener('click', () => {
    window.showScreen("scr-1779422322698");
  });

  // ログアウト処理
  container.querySelector('#logout-button').addEventListener('click', () => {
    localStorage.removeItem('rememberedUser');
    window.location.reload();
  });

  // パスワードリセットリンク
  container.querySelector('#forgot-password').addEventListener('click', (e) => {
    e.preventDefault();
    alert('パスワードリセット機能は管理者にお問い合わせください。');
  });

  // ヘルプ・お問い合わせリンク
  container.querySelector('#help-link').addEventListener('click', (e) => {
    e.preventDefault();
    alert('ヘルプページは準備中です。');
  });

  container.querySelector('#contact-link').addEventListener('click', (e) => {
    e.preventDefault();
    alert('お問い合わせは system-admin@company.com までご連絡ください。');
  });

  // 記憶されたユーザーIDを復元
  const rememberedUser = localStorage.getItem('rememberedUser');
  if (rememberedUser) {
    container.querySelector('#user-id').value = rememberedUser;
    container.querySelector('#remember-me').checked = true;
  }

  // 言語切り替え（プレースホルダー）
  container.querySelector('#language-select').addEventListener('change', (e) => {
    // 実際の実装では多言語対応を行う
    console.log('言語切り替え:', e.target.value);
  });

  // フォーカス時のスタイル適用
  const inputs = container.querySelectorAll('input[type="text"], input[type="password"]');
  inputs.forEach(input => {
    input.addEventListener('focus', () => {
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });

    input.addEventListener('blur', () => {
      input.style.borderColor = 'rgba(255,255,255,0.18)';
      input.style.boxShadow = 'none';
    });
  });
}

function(container, apiUrl, tables) {
  let uploadedFile = null;
  let detectedDocType = null;
  let confidenceLevel = 0;

  // DOM要素の取得
  const dropZone = container.querySelector('#drop-zone');
  const fileInput = container.querySelector('#file-input');
  const uploadProgress = container.querySelector('#upload-progress');
  const progressBar = container.querySelector('#progress-bar');
  const progressPercent = container.querySelector('#progress-percent');
  const uploadedFiles = container.querySelector('#uploaded-files');
  const fileName = container.querySelector('#file-name');
  const fileSize = container.querySelector('#file-size');
  const removeFileBtn = container.querySelector('#remove-file');
  const detectionResult = container.querySelector('#detection-result');
  const detectedType = container.querySelector('#detected-type');
  const confidenceBar = container.querySelector('#confidence-bar');
  const confidencePercentEl = container.querySelector('#confidence-percent');
  const manualTypeSelect = container.querySelector('#manual-type');
  const approvalFlowResult = container.querySelector('#approval-flow-result');
  const noFlowMessage = container.querySelector('#no-flow-message');
  const flowName = container.querySelector('#flow-name');
  const approversList = container.querySelector('#approvers-list');

  // ファイルサイズフォーマット関数
  function formatFileSize(bytes) {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }

  // ファイル処理関数
  function handleFile(file) {
    if (file.size > 10 * 1024 * 1024) {
      alert('ファイルサイズが10MBを超えています。');
      return;
    }

    uploadedFile = file;
    fileName.textContent = file.name;
    fileSize.textContent = formatFileSize(file.size);

    // アップロード進捗シミュレーション
    uploadProgress.style.display = 'block';
    uploadedFiles.style.display = 'none';

    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress >= 100) {
        progress = 100;
        clearInterval(interval);

        setTimeout(() => {
          uploadProgress.style.display = 'none';
          uploadedFiles.style.display = 'block';

          // AI判別シミュレーション
          simulateAIDetection();
        }, 500);
      }

      progressBar.style.width = progress + '%';
      progressPercent.textContent = Math.round(progress) + '%';
    }, 200);
  }

  // AI判別シミュレーション
  function simulateAIDetection() {
    const docTypes = [
      { type: 'vacation', name: '休暇申請', confidence: 85 },
      { type: 'expense', name: '経費申請', confidence: 92 },
      { type: 'approval', name: '稟議書', confidence: 78 },
      { type: 'purchase', name: '購買申請', confidence: 88 },
      { type: 'contract', name: '契約書', confidence: 95 },
      { type: 'report', name: '報告書', confidence: 73 }
    ];

    const randomType = docTypes[Math.floor(Math.random() * docTypes.length)];
    detectedDocType = randomType.type;
    confidenceLevel = randomType.confidence;

    detectedType.textContent = randomType.name;
    confidenceBar.style.width = confidenceLevel + '%';
    confidencePercentEl.textContent = confidenceLevel + '%';

    detectionResult.style.display = 'block';
    manualTypeSelect.value = detectedDocType;

    // 承認フロー設定
    updateApprovalFlow(detectedDocType);
  }

  // 承認フロー更新
  function updateApprovalFlow(docType) {
    if (!docType) {
      approvalFlowResult.style.display = 'none';
      noFlowMessage.style.display = 'block';
      return;
    }

    const flowConfigs = {
      vacation: {
        name: '休暇申請承認フロー',
        approvers: [
          { step: 1, name: '直属上司', role: '課長', user: '田中 太郎' },
          { step: 2, name: '部門長', role: '部長', user: '佐藤 花子' }
        ]
      },
      expense: {
        name: '経費申請承認フロー',
        approvers: [
          { step: 1, name: '直属上司', role: '課長', user: '田中 太郎' },
          { step: 2, name: '経理担当', role: '経理課長', user: '山田 次郎' },
          { step: 3, name: '部門長', role: '部長', user: '佐藤 花子' }
        ]
      },
      approval: {
        name: '稟議書承認フロー',
        approvers: [
          { step: 1, name: '直属上司', role: '課長', user: '田中 太郎' },
          { step: 2, name: '部門長', role: '部長', user: '佐藤 花子' },
          { step: 3, name: '役員', role: '取締役', user: '鈴木 一郎' }
        ]
      },
      purchase: {
        name: '購買申請承認フロー',
        approvers: [
          { step: 1, name: '直属上司', role: '課長', user: '田中 太郎' },
          { step: 2, name: '購買担当', role: '購買課長', user: '高橋 三郎' }
        ]
      },
      contract: {
        name: '契約書承認フロー',
        approvers: [
          { step: 1, name: '法務担当', role: '法務課長', user: '伊藤 四郎' },
          { step: 2, name: '部門長', role: '部長', user: '佐藤 花子' },
          { step: 3, name: '役員', role: '取締役', user: '鈴木 一郎' }
        ]
      },
      report: {
        name: '報告書承認フロー',
        approvers: [
          { step: 1, name: '直属上司', role: '課長', user: '田中 太郎' }
        ]
      }
    };

    const config = flowConfigs[docType];
    if (config) {
      flowName.textContent = config.name;

      const approversHtml = config.approvers.map(approver => `
        <div style="display: flex; align-items: center; padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,0.08);">
          <div style="width: 24px; height: 24px; background: var(--primary); color: #fff; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 600; margin-right: 8px;">
            ${approver.step}
          </div>
          <div style="flex: 1;">
            <div style="font-size: 13px; color: var(--text); font-weight: 500;">${approver.user}</div>
            <div style="font-size: 11px; color: var(--text-muted);">${approver.role} (${approver.name})</div>
          </div>
        </div>
      `).join('');

      approversList.innerHTML = approversHtml;
      approvalFlowResult.style.display = 'block';
      noFlowMessage.style.display = 'none';
    }
  }

  // ドラッグ&ドロップイベント
  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--primary)';
    dropZone.style.background = 'rgba(255,255,255,0.05)';
  });

  dropZone.addEventListener('dragleave', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'rgba(255,255,255,0.18)';
    dropZone.style.background = 'rgba(0,0,0,0.15)';
  });

  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'rgba(255,255,255,0.18)';
    dropZone.style.background = 'rgba(0,0,0,0.15)';

    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFile(files[0]);
    }
  });

  dropZone.addEventListener('click', () => {
    fileInput.click();
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFile(e.target.files[0]);
    }
  });

  // ファイル削除
  removeFileBtn.addEventListener('click', () => {
    uploadedFile = null;
    uploadedFiles.style.display = 'none';
    detectionResult.style.display = 'none';
    manualTypeSelect.value = '';
    updateApprovalFlow(null);
    fileInput.value = '';
  });

  // 手動文書種別選択
  manualTypeSelect.addEventListener('change', (e) => {
    updateApprovalFlow(e.target.value);
  });

  // 文書種別判定ボタン
  container.querySelector('#btn-auto-detect').addEventListener('click', () => {
    window.showScreen("scr-1779422563059");
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('入力内容が失われますが、よろしいですか？')) {
      // フォームリセット
      uploadedFile = null;
      uploadedFiles.style.display = 'none';
      detectionResult.style.display = 'none';
      container.querySelector('#application-title').value = '';
      container.querySelector('#application-content').value = '';
      container.querySelector('input[name="urgency"][value="normal"]').checked = true;
      manualTypeSelect.value = '';
      updateApprovalFlow(null);
      fileInput.value = '';
    }
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const title = container.querySelector('#application-title').value.trim();
    const content = container.querySelector('#application-content').value.trim();
    const urgency = container.querySelector('input[name="urgency"]:checked')?.value;
    const docType = manualTypeSelect.value;

    if (!uploadedFile) {
      alert('ファイルをアップロードしてください。');
      return;
    }

    if (!title) {
      alert('申請タイトルを入力してください。');
      return;
    }

    if (!content) {
      alert('申請内容を入力してください。');
      return;
    }

    if (!docType) {
      alert('文書種別を選択してください。');
      return;
    }

    // 申請書類データの保存
    const applicationData = {
      申請者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
      申請種別: docType,
      申請タイトル: title,
      申請内容: content,
      承認状態: '申請中',
      承認段階: 1,
      緊急フラグ: urgency === 'urgent' || urgency === 'high',
      添付ファイル有無: true,
      作成者ID: 'current-user-id'
    };

    try {
      const saved = await window.aivicApi.save(1, applicationData); // tables[1] = 申請書類
      if (saved) {
        alert('申請書類が正常に登録されました。');
        // フォームリセット
        uploadedFile = null;
        uploadedFiles.style.display = 'none';
        detectionResult.style.display = 'none';
        container.querySelector('#application-title').value = '';
        container.querySelector('#application-content').value = '';
        container.querySelector('input[name="urgency"][value="normal"]').checked = true;
        manualTypeSelect.value = '';
        updateApprovalFlow(null);
        fileInput.value = '';
      } else {
        alert('申請書類の登録に失敗しました。');
      }
    } catch (error) {
      console.error('保存エラー:', error);
      alert('申請書類の登録中にエラーが発生しました。');
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#approval-tbody');

  // 統計更新関数
  function updateStats(rows) {
    const approved = rows.filter(r => r.承認状態 === '承認済').length;
    const pending = rows.filter(r => r.承認状態 === '申請中').length;
    const delayed = rows.filter(r => {
      if (r.承認状態 !== '申請中') return false;
      const createdDate = new Date(r.作成日時);
      const daysDiff = Math.floor((new Date() - createdDate) / (1000 * 60 * 60 * 24));
      return daysDiff > 3;
    }).length;
    const urgent = rows.filter(r => r.緊急フラグ === true).length;

    container.querySelector('#stat-approved').textContent = approved;
    container.querySelector('#stat-pending').textContent = pending;
    container.querySelector('#stat-delayed').textContent = delayed;
    container.querySelector('#stat-urgent').textContent = urgent;
  }

  // 進捗バー生成関数
  function createProgressBar(currentStep, totalSteps) {
    const progress = Math.round((currentStep / totalSteps) * 100);
    return `
      <div style="display: flex; align-items: center; gap: 6px;">
        <div style="flex: 1; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden;">
          <div style="height: 100%; background: var(--primary); width: ${progress}%"></div>
        </div>
        <span style="font-size: 11px; color: var(--text-muted);">${currentStep}/${totalSteps}</span>
      </div>
    `;
  }

  // 遅延日数計算関数
  function calculateDelayDays(createdDate, status) {
    if (status === '承認済' || status === '却下' || status === '取下げ') return 0;
    const created = new Date(createdDate);
    const now = new Date();
    const daysDiff = Math.floor((now - created) / (1000 * 60 * 60 * 24));
    return Math.max(0, daysDiff - 3); // 3日を基準期限とする
  }

  // 優先度バッジ生成関数
  function createPriorityBadge(isUrgent, priority) {
    if (isUrgent) {
      return '<span style="padding: 2px 6px; background: rgba(239, 68, 68, 0.2); color: #ef4444; border-radius: 4px; font-size: 11px; font-weight: 500;">緊急</span>';
    }
    const colors = {
      1: { bg: 'rgba(156, 163, 175, 0.2)', color: '#9ca3af' },
      2: { bg: 'rgba(59, 130, 246, 0.2)', color: '#3b82f6' },
      3: { bg: 'rgba(245, 158, 11, 0.2)', color: '#f59e0b' },
      4: { bg: 'rgba(239, 68, 68, 0.2)', color: '#ef4444' }
    };
    const labels = { 1: '低', 2: '通常', 3: '高', 4: '緊急' };
    const style = colors[priority] || colors[2];
    return `<span style="padding: 2px 6px; background: ${style.bg}; color: ${style.color}; border-radius: 4px; font-size: 11px; font-weight: 500;">${labels[priority] || '通常'}</span>`;
  }

  // 承認状態バッジ生成関数
  function createStatusBadge(status) {
    const colors = {
      '申請中': { bg: 'rgba(245, 158, 11, 0.2)', color: '#f59e0b' },
      '承認済': { bg: 'rgba(34, 197, 94, 0.2)', color: '#22c55e' },
      '却下': { bg: 'rgba(239, 68, 68, 0.2)', color: '#ef4444' },
      '取下げ': { bg: 'rgba(156, 163, 175, 0.2)', color: '#9ca3af' }
    };
    const style = colors[status] || colors['申請中'];
    return `<span style="padding: 2px 6px; background: ${style.bg}; color: ${style.color}; border-radius: 4px; font-size: 11px; font-weight: 500;">${status}</span>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const delayDays = calculateDelayDays(r.作成日時, r.承認状態);
      const progressBar = createProgressBar(r.承認段階 || 1, 3);
      const priorityBadge = createPriorityBadge(r.緊急フラグ, r.優先度);
      const statusBadge = createStatusBadge(r.承認状態);

      return `
        <tr data-id="${r.id}" style="cursor: pointer;">
          <td style="font-size: 12px; color: var(--text-muted);">${r.id?.substring(0, 8) || ''}</td>
          <td>${r.申請種別 || ''}</td>
          <td>${r.申請者名 || ''}</td>
          <td style="font-size: 12px;">${r.作成日時 ? new Date(r.作成日時).toLocaleDateString() : ''}</td>
          <td>${statusBadge}</td>
          <td style="width: 120px;">${progressBar}</td>
          <td>${r.現在承認者名 || '-'}</td>
          <td style="text-align: center; ${delayDays > 0 ? 'color: #ef4444; font-weight: 500;' : ''}">${delayDays > 0 ? delayDays + '日' : '-'}</td>
          <td>${priorityBadge}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px;">案件詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updateStats(rows);
  }

  // 初期データ描画
  renderRows(tables[0].records || []);

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const documentType = container.querySelector('#filter-document-type').value;
    const approvalStatus = container.querySelector('#filter-approval-status').value;
    const applicant = container.querySelector('#search-applicant').value.toLowerCase();
    const approver = container.querySelector('#search-approver').value.toLowerCase();

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      if (documentType && r.申請種別 !== documentType) return false;
      if (approvalStatus && r.承認状態 !== approvalStatus) return false;
      if (applicant && !r.申請者名?.toLowerCase().includes(applicant)) return false;
      if (approver && !r.現在承認者名?.toLowerCase().includes(approver)) return false;
      return true;
    });

    renderRows(filtered);
  });

  // クリア機能
  container.querySelector('#btn-clear').addEventListener('click', async () => {
    container.querySelector('#filter-document-type').value = '';
    container.querySelector('#filter-approval-status').value = '';
    container.querySelector('#search-applicant').value = '';
    container.querySelector('#search-approver').value = '';

    const rows = await window.aivicApi.list(0);
    if (rows) renderRows(rows);
  });

  // 遅延案件確認ボタン
  container.querySelector('#btn-delay-check').addEventListener('click', () => {
    window.showScreen("scr-1779422271790");
  });

  // ルート変更ボタン
  container.querySelector('#btn-route-change').addEventListener('click', () => {
    window.showScreen("scr-1779422283293");
  });

  // 行クリック・案件詳細ボタン
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    const row = e.target.closest('tr[data-id]');

    if (detailBtn || (row && !e.target.closest('button'))) {
      window.showScreen("scr-1779422369173");
    }
  });

  // 定期更新（30秒ごと）
  setInterval(async () => {
    const rows = await window.aivicApi.list(0);
    if (rows) {
      // 現在のフィルター条件を保持して更新
      const documentType = container.querySelector('#filter-document-type').value;
      const approvalStatus = container.querySelector('#filter-approval-status').value;
      const applicant = container.querySelector('#search-applicant').value.toLowerCase();
      const approver = container.querySelector('#search-approver').value.toLowerCase();

      let filtered = rows;
      if (documentType || approvalStatus || applicant || approver) {
        filtered = rows.filter(r => {
          if (documentType && r.申請種別 !== documentType) return false;
          if (approvalStatus && r.承認状態 !== approvalStatus) return false;
          if (applicant && !r.申請者名?.toLowerCase().includes(applicant)) return false;
          if (approver && !r.現在承認者名?.toLowerCase().includes(approver)) return false;
          return true;
        });
      }

      renderRows(filtered);
    }
  }, 30000);
}

function(container, apiUrl, tables) {
  let selectedApplicationId = null;
  let currentApplications = [];
  let currentApprovalHistory = [];

  // 申請書類一覧の描画
  function renderApplicationsList(applications) {
    const listContainer = container.querySelector('#applications-list');
    if (!applications || applications.length === 0) {
      listContainer.innerHTML = '<div style="text-align: center; padding: 20px; color: var(--text-muted); font-size: 12px;">承認待ちの申請はありません</div>';
      return;
    }

    listContainer.innerHTML = applications.map(app => {
      const isSelected = selectedApplicationId === app.id;
      const statusColor = getStatusColor(app.承認状態);
      const priorityText = app.緊急フラグ ? '緊急' : '通常';

      return `
        <div class="application-item" data-id="${app.id}" 
             style="padding: 10px; border: 1px solid ${isSelected ? 'var(--primary)' : 'rgba(255,255,255,0.1)'}; 
                    border-radius: 6px; cursor: pointer; background: ${isSelected ? 'rgba(var(--primary-rgb), 0.05)' : 'rgba(0,0,0,0.1)'}; 
                    transition: all 0.15s;">
          <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px;">
            <div style="font-size: 12px; font-weight: 500; color: var(--text); overflow: hidden; text-overflow: ellipsis;">${app.申請タイトル || ''}</div>
            ${app.緊急フラグ ? '<span style="font-size: 10px; padding: 2px 4px; background: rgba(220,38,38,0.15); color: #dc2626; border-radius: 3px;">緊急</span>' : ''}
          </div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">${app.申請種別 || ''}</div>
          <div style="display: flex; align-items: center; justify-content: space-between;">
            <span style="font-size: 10px; padding: 2px 6px; background: ${statusColor.bg}; color: ${statusColor.text}; border-radius: 3px;">${app.承認状態}</span>
            <span style="font-size: 10px; color: var(--text-muted);">${formatDate(app.作成日時)}</span>
          </div>
        </div>
      `;
    }).join('');
  }

  // 申請書類詳細の表示
  function showApplicationDetail(application) {
    const detailSection = container.querySelector('#application-detail');
    const noSelectionSection = container.querySelector('#no-selection');
    const approvalSection = container.querySelector('#approval-actions');
    const noApprovalSection = container.querySelector('#no-approval-action');

    if (!application) {
      detailSection.style.display = 'none';
      noSelectionSection.style.display = 'block';
      approvalSection.style.display = 'none';
      noApprovalSection.style.display = 'block';
      return;
    }

    // 詳細情報の表示
    container.querySelector('#detail-title').textContent = application.申請タイトル || '';
    container.querySelector('#applicant-name').textContent = application.申請者名 || '';
    container.querySelector('#application-date').textContent = formatDateTime(application.作成日時);
    container.querySelector('#application-type').textContent = application.申請種別 || '';
    container.querySelector('#application-amount').textContent = application.申請金額 ? `¥${application.申請金額.toLocaleString()}` : '－';
    container.querySelector('#application-content').textContent = application.申請内容 || '';

    // ステータスバッジ
    const statusColor = getStatusColor(application.承認状態);
    const statusBadge = container.querySelector('#status-badge');
    statusBadge.textContent = application.承認状態;
    statusBadge.style.background = statusColor.bg;
    statusBadge.style.color = statusColor.text;

    // 優先度バッジ
    const priorityBadge = container.querySelector('#priority-badge');
    priorityBadge.textContent = application.緊急フラグ ? '緊急' : '通常';
    priorityBadge.style.display = application.緊急フラグ ? 'inline-block' : 'none';

    // 承認フロー進捗の表示
    renderApprovalFlow(application);

    // 添付ファイルの表示
    const attachmentsSection = container.querySelector('#attachments-section');
    if (application.添付ファイル有無) {
      attachmentsSection.style.display = 'block';
      container.querySelector('#attachments-list').innerHTML = `
        <div style="padding: 6px 10px; background: rgba(0,0,0,0.15); border-radius: 4px; font-size: 12px; color: var(--text);">
          📎 申請書.pdf
        </div>
      `;
    } else {
      attachmentsSection.style.display = 'none';
    }

    detailSection.style.display = 'block';
    noSelectionSection.style.display = 'none';
    approvalSection.style.display = 'block';
    noApprovalSection.style.display = 'none';

    // 承認履歴の読み込み
    loadApprovalHistory(application.id);
  }

  // 承認フロー進捗の表示
  function renderApprovalFlow(application) {
    const flowContainer = container.querySelector('#approval-flow');
    const currentStep = application.承認段階 || 1;
    const totalSteps = 3; // 仮の承認段数

    let flowHtml = '';
    for (let i = 1; i <= totalSteps; i++) {
      const isActive = i === currentStep;
      const isCompleted = i < currentStep;
      const stepClass = isCompleted ? 'completed' : (isActive ? 'active' : 'pending');

      flowHtml += `
        <div style="display: flex; align-items: center;">
          <div style="width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 500;
                      background: ${isCompleted ? 'var(--primary)' : (isActive ? 'var(--primary)' : 'rgba(255,255,255,0.1)')}; 
                      color: ${isCompleted || isActive ? '#fff' : 'var(--text-muted)'};">
            ${isCompleted ? '✓' : i}
          </div>
          <div style="margin-left: 8px; font-size: 11px; color: ${isActive ? 'var(--text)' : 'var(--text-muted)'};">
            ${i === 1 ? '課長承認' : i === 2 ? '部長承認' : '役員承認'}
          </div>
        </div>
      `;

      if (i < totalSteps) {
        flowHtml += `<div style="width: 20px; height: 2px; background: ${i < currentStep ? 'var(--primary)' : 'rgba(255,255,255,0.1)'};"></div>`;
      }
    }

    flowContainer.innerHTML = flowHtml;
  }

  // 承認履歴の読み込み
  async function loadApprovalHistory(applicationId) {
    try {
      const history = await window.aivicApi.list(4); // 承認履歴テーブル
      if (history) {
        const filteredHistory = history.filter(h => h.申請書類ID === applicationId);
        renderApprovalHistory(filteredHistory);
      }
    } catch (error) {
      console.error('承認履歴の読み込みに失敗:', error);
    }
  }

  // 承認履歴の表示
  function renderApprovalHistory(history) {
    const tbody = container.querySelector('#approval-history-tbody');
    if (!history || history.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; color: var(--text-muted); font-size: 12px;">承認履歴はありません</td></tr>';
      return;
    }

    tbody.innerHTML = history.map(h => `
      <tr>
        <td>${h.承認者名 || ''}</td>
        <td>
          <span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; 
                       background: ${getStatusColor(h.承認結果).bg}; 
                       color: ${getStatusColor(h.承認結果).text};">
            ${h.承認結果}
          </span>
        </td>
        <td style="font-size: 12px;">${formatDateTime(h.承認日時)}</td>
        <td style="font-size: 12px;">${h.承認コメント || ''}</td>
      </tr>
    `).join('');
  }

  // ステータス色の取得
  function getStatusColor(status) {
    const colors = {
      '申請中': { bg: 'rgba(59,130,246,0.15)', text: '#3b82f6' },
      '承認済': { bg: 'rgba(34,197,94,0.15)', text: '#22c55e' },
      '差戻し': { bg: 'rgba(220,38,38,0.15)', text: '#dc2626' },
      '保留': { bg: 'rgba(245,158,11,0.15)', text: '#f59e0b' },
      '却下': { bg: 'rgba(220,38,38,0.15)', text: '#dc2626' }
    };
    return colors[status] || { bg: 'rgba(156,163,175,0.15)', text: '#9ca3af' };
  }

  // 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return `${date.getMonth() + 1}/${date.getDate()}`;
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return `${date.getFullYear()}/${String(date.getMonth() + 1).padStart(2, '0')}/${String(date.getDate()).padStart(2, '0')} ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
  }

  // 確認モーダルの表示
  function showConfirmModal(title, message, onConfirm) {
    const modal = container.querySelector('#confirmation-modal');
    container.querySelector('#modal-title').textContent = title;
    container.querySelector('#modal-message').textContent = message;
    modal.style.display = 'flex';

    const confirmBtn = container.querySelector('#modal-confirm');
    const cancelBtn = container.querySelector('#modal-cancel');

    const handleConfirm = () => {
      modal.style.display = 'none';
      onConfirm();
      confirmBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
    };

    const handleCancel = () => {
      modal.style.display = 'none';
      confirmBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
    };

    confirmBtn.addEventListener('click', handleConfirm);
    cancelBtn.addEventListener('click', handleCancel);
  }

  // 承認処理の実行
  async function processApproval(action, comment) {
    if (!selectedApplicationId) return;

    try {
      const application = currentApplications.find(app => app.id === selectedApplicationId);
      if (!application) return;

      // 承認履歴の追加
      const historyData = {
        申請書類ID: selectedApplicationId,
        承認ステップID: `step-${Date.now()}`,
        承認者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
        承認結果: action,
        承認コメント: comment,
        承認日時: new Date().toISOString(),
        承認順序: 1
      };

      const savedHistory = await window.aivicApi.save(4, historyData);
      if (savedHistory) {
        // 申請書類のステータス更新
        const updatedApplication = await window.aivicApi.update(1, selectedApplicationId, {
          承認状態: action,
          最終承認日時: new Date().toISOString()
        });

        if (updatedApplication) {
          // 画面の更新
          await loadApplications();
          const updatedApp = currentApplications.find(app => app.id === selectedApplicationId);
          showApplicationDetail(updatedApp);

          // フォームのクリア
          container.querySelector('#approval-comment').value = '';
          container.querySelector('#rejection-reason').value = '';
        }
      }
    } catch (error) {
      console.error('承認処理に失敗:', error);
      alert('承認処理に失敗しました。再度お試しください。');
    }
  }

  // 申請書類一覧の読み込み
  async function loadApplications() {
    try {
      const applications = await window.aivicApi.list(1);
      if (applications) {
        // 承認待ちの申請のみフィルタリング
        currentApplications = applications.filter(app => 
          app.承認状態 === '申請中' || app.承認状態 === '保留'
        );
        renderApplicationsList(currentApplications);
      }
    } catch (error) {
      console.error('申請書類の読み込みに失敗:', error);
      currentApplications = tables[1]?.records || [];
      renderApplicationsList(currentApplications);
    }
  }

  // 検索機能
  function searchApplications() {
    const keyword = container.querySelector('#search-applications').value.toLowerCase();
    const filtered = currentApplications.filter(app => 
      (app.申請タイトル || '').toLowerCase().includes(keyword) ||
      (app.申請種別 || '').toLowerCase().includes(keyword) ||
      (app.申請者名 || '').toLowerCase().includes(keyword)
    );
    renderApplicationsList(filtered);
  }

  // イベントリスナーの設定
  container.addEventListener('click', async (e) => {
    // 申請書類の選択
    const applicationItem = e.target.closest('.application-item');
    if (applicationItem) {
      selectedApplicationId = applicationItem.dataset.id;
      const application = currentApplications.find(app => app.id === selectedApplicationId);
      showApplicationDetail(application);
      renderApplicationsList(currentApplications); // 選択状態を更新
      return;
    }

    // 承認ボタン
    if (e.target.closest('#btn-approve')) {
      const comment = container.querySelector('#approval-comment').value;
      showConfirmModal(
        '承認確認',
        'この申請を承認しますか？',
        () => processApproval('承認済', comment)
      );
      return;
    }

    // 差戻しボタン
    if (e.target.closest('#btn-reject')) {
      const reason = container.querySelector('#rejection-reason').value;
      if (!reason.trim()) {
        alert('差戻し理由を入力してください。');
        return;
      }
      showConfirmModal(
        '差戻し確認',
        'この申請を差戻しますか？',
        () => processApproval('差戻し', reason)
      );
      return;
    }

    // 保留ボタン
    if (e.target.closest('#btn-hold')) {
      const comment = container.querySelector('#approval-comment').value;
      showConfirmModal(
        '保留確認',
        'この申請を保留にしますか？',
        () => processApproval('保留', comment)
      );
      return;
    }

    // 更新ボタン
    if (e.target.closest('#btn-refresh')) {
      await loadApplications();
      return;
    }
  });

  // 検索入力のイベントリスナー
  container.querySelector('#search-applications').addEventListener('input', searchApplications);

  // 初期データの読み込み
  loadApplications();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#delay-cases-tbody');
  const totalCountEl = container.querySelector('#total-count');
  const selectedCountEl = container.querySelector('#selected-count');
  const selectAllCheckbox = container.querySelector('#select-all');
  const bulkNotifyBtn = container.querySelector('#btn-bulk-notify');

  // 遅延日数とレベルを計算する関数
  function calculateDelayInfo(applicationDate, currentDate = new Date()) {
    const appDate = new Date(applicationDate);
    const diffTime = currentDate - appDate;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    let level = '軽微';
    if (diffDays > 7) level = '緊急';
    else if (diffDays > 3) level = '注意';

    return { days: diffDays, level };
  }

  // 遅延レベルのスタイルを取得
  function getDelayLevelStyle(level) {
    const styles = {
      '軽微': 'background: rgba(59, 130, 246, 0.1); color: #3b82f6; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '注意': 'background: rgba(245, 158, 11, 0.1); color: #f59e0b; padding: 2px 6px; border-radius: 4px; font-size: 11px;',
      '緊急': 'background: rgba(239, 68, 68, 0.1); color: #ef4444; padding: 2px 6px; border-radius: 4px; font-size: 11px;'
    };
    return styles[level] || styles['軽微'];
  }

  // テーブル再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="11" style="text-align: center; padding: 20px; color: var(--text-muted);">遅延案件はありません</td></tr>';
      totalCountEl.textContent = '0件';
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const delayInfo = calculateDelayInfo(row.作成日時 || row.申請日時 || new Date().toISOString());
      const applicantName = row.申請者名 || '不明';
      const approverName = row.現在承認者名 || '未設定';
      const lastUpdate = row.更新日時 ? new Date(row.更新日時).toLocaleDateString('ja-JP') : '-';

      return `
        <tr data-id="${row.id}" style="height: 36px;">
          <td style="padding: 6px 10px;">
            <input type="checkbox" class="row-checkbox" data-id="${row.id}" style="accent-color: var(--primary);">
          </td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text-muted);">${row.id?.substring(0, 8) || '-'}</td>
          <td style="padding: 6px 10px;">${row.申請種別 || '-'}</td>
          <td style="padding: 6px 10px; max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${row.申請タイトル || '-'}</td>
          <td style="padding: 6px 10px;">${applicantName}</td>
          <td style="padding: 6px 10px;">${approverName}</td>
          <td style="padding: 6px 10px;">${row.承認状態 || '承認待ち'}</td>
          <td style="padding: 6px 10px; font-weight: 600; color: #ef4444;">${delayInfo.days}日</td>
          <td style="padding: 6px 10px;">
            <span style="${getDelayLevelStyle(delayInfo.level)}">${delayInfo.level}</span>
          </td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text-muted);">${lastUpdate}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn notify-btn" data-id="${row.id}" style="font-size: 11px; padding: 4px 8px;">催促送信</button>
          </td>
        </tr>
      `;
    }).join('');

    totalCountEl.textContent = `${rows.length}件`;
    updateSelectedCount();
  }

  // 選択数を更新
  function updateSelectedCount() {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    const checkedBoxes = container.querySelectorAll('.row-checkbox:checked');
    selectedCountEl.textContent = `${checkedBoxes.length}件選択中`;
    bulkNotifyBtn.disabled = checkedBoxes.length === 0;

    selectAllCheckbox.checked = checkboxes.length > 0 && checkedBoxes.length === checkboxes.length;
    selectAllCheckbox.indeterminate = checkedBoxes.length > 0 && checkedBoxes.length < checkboxes.length;
  }

  // フィルタリング関数
  function filterRows(rows) {
    const documentType = container.querySelector('#filter-document-type').value;
    const approvalStatus = container.querySelector('#filter-approval-status').value;
    const delayLevel = container.querySelector('#filter-delay-level').value;

    return rows.filter(row => {
      const delayInfo = calculateDelayInfo(row.作成日時 || row.申請日時 || new Date().toISOString());

      if (documentType && row.申請種別 !== documentType) return false;
      if (approvalStatus && row.承認状態 !== approvalStatus) return false;
      if (delayLevel && delayInfo.level !== delayLevel) return false;

      return true;
    });
  }

  // 初期データ描画（遅延案件のみ表示）
  const initialData = tables[0]?.records || [];
  const delayedCases = initialData.filter(row => {
    const delayInfo = calculateDelayInfo(row.作成日時 || row.申請日時 || new Date().toISOString());
    return delayInfo.days > 0 && (row.承認状態 === '承認待ち' || row.承認状態 === '差戻し' || row.承認状態 === '保留');
  });
  renderRows(delayedCases);

  // 検索ボタンイベント
  container.querySelector('#btn-search').addEventListener('click', async () => {
    try {
      const allRows = await window.aivicApi.list(0);
      if (allRows) {
        const delayedCases = allRows.filter(row => {
          const delayInfo = calculateDelayInfo(row.作成日時 || row.申請日時 || new Date().toISOString());
          return delayInfo.days > 0 && (row.承認状態 === '承認待ち' || row.承認状態 === '差戻し' || row.承認状態 === '保留');
        });
        const filteredRows = filterRows(delayedCases);
        renderRows(filteredRows);
      }
