            通知タイトル: '承認遅延の催促',
            通知内容: '承認が遅延している申請があります。確認をお願いします。',
            送信方法: 'メール',
            送信状態: '送信完了',
            送信日時: new Date().toISOString(),
            既読フラグ: false,
            再送回数: 0,
            作成者ID: 'current-user-id'
          });
          alert('催促通知を送信しました。');
        } catch (error) {
          alert('送信に失敗しました。');
        }
      }
    }
  });

  // 一括催促送信
  bulkNotifyBtn.addEventListener('click', async () => {
