            既読フラグ: false,
            再送回数: 0,
            作成者ID: 'current-user-id'
          });
        }
        alert(`${checkedBoxes.length}件の催促通知を送信しました。`);

        // チェックボックスをクリア
        checkedBoxes.forEach(cb => cb.checked = false);
