function(container, apiUrl, tables) {
  // テーブルインデックスの定義
  const APPLICATION_TABLE = 1; // 申請書類
  const APPROVAL_FLOW_TABLE = 3; // 承認フロー定義
  const APPROVAL_STEP_TABLE = 4; // 承認ステップ
  const PROCESSING_ROUTE_TABLE = 6; // 処理ルート
  const USER_TABLE = 0; // ユーザー

  let currentApplicationId = null;
  let currentRouteData = null;

  // 承認ステップテーブル再描画関数
  function renderApprovalSteps(steps) {
    const tbody = container.querySelector("#approval-steps-tbody");
    if (!steps || steps.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px;">承認ステップがありません</td></tr>';
      return;
    }

    tbody.innerHTML = steps.map(step => `
      <tr data-id="${step.id}">
        <td style="padding: 6px 10px; font-size: 12px;">${step.ステップ番号 || step.承認段階 || '-'}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${step.承認者名 || step.承認者ID || '-'}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${step.承認者役職 || step.役職 || '-'}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${step.期限日時 ? new Date(step.期限日時).toLocaleDateString() : '-'}</td>
        <td style="padding: 6px 10px; font-size: 12px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${getStatusColor(step.承認状態)};">
            ${step.承認状態 || '未承認'}
          </span>
        </td>
      </tr>
    `).join("");
  }

  // ステータス色取得
  function getStatusColor(status) {
    switch(status) {
      case '承認済': return 'rgba(34, 197, 94, 0.2)';
      case '否認': return 'rgba(239, 68, 68, 0.2)';
      case '保留': return 'rgba(245, 158, 11, 0.2)';
      default: return 'rgba(156, 163, 175, 0.2)';
    }
  }

  // 申請書類選択時の処理
  async function handleApplicationSelect(applicationId) {
    if (!applicationId) {
      container.querySelector("#input-status").value = "";
      container.querySelector("#current-route").textContent = "申請書類を選択してください";
      renderApprovalSteps([]);
      return;
    }

    currentApplicationId = applicationId;

    try {
      // 申請書類の詳細を取得
      const applications = await window.aivicApi.list(APPLICATION_TABLE);
      const application = applications.find(app => app.id === applicationId);

      if (application) {
        container.querySelector("#input-status").value = application.承認状態 || '申請中';

        // 現在の処理ルートを表示
        const routes = await window.aivicApi.list(PROCESSING_ROUTE_TABLE);
        const currentRoute = routes.find(route => route.申請書類ID === applicationId);

        if (currentRoute) {
          currentRouteData = currentRoute;
          container.querySelector("#current-route").textContent = 
            `${currentRoute.処理状況} - ステップ${currentRoute.現在ステップ番号} (${currentRoute.現在承認者ID || '未設定'})`;
        } else {
          container.querySelector("#current-route").textContent = "処理ルートが設定されていません";
        }

        // 承認ステップを取得・表示
        const steps = await window.aivicApi.list(APPROVAL_STEP_TABLE);
        const applicationSteps = steps.filter(step => step.申請書類ID === applicationId);
        renderApprovalSteps(applicationSteps);
      }
    } catch (error) {
      console.error('申請書類情報の取得に失敗しました:', error);
    }
  }

  // 新しい処理ルート選択時の処理
  async function handleNewRouteSelect(routeId) {
    if (!routeId) {
      renderApprovalSteps([]);
      return;
    }

    try {
      // 新しいルートの承認フロー定義を取得
      const flows = await window.aivicApi.list(APPROVAL_FLOW_TABLE);
      const selectedFlow = flows.find(flow => flow.id === routeId);

      if (selectedFlow) {
        // サンプルの承認ステップを表示
        const sampleSteps = [
          {
            id: 'sample1',
            ステップ番号: 1,
            承認者名: selectedFlow.承認者ユーザーID || '田中部長',
            承認者役職: selectedFlow.承認者役職 || '部長',
            期限日時: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(),
            承認状態: '未承認'
          }
        ];

        if (routeId === '3') { // 特別承認フロー
          sampleSteps.push({
            id: 'sample2',
            ステップ番号: 2,
            承認者名: '佐藤課長',
            承認者役職: '課長',
            期限日時: new Date(Date.now() + 5 * 24 * 60 * 60 * 1000).toISOString(),
            承認状態: '未承認'
          });
          sampleSteps.push({
            id: 'sample3',
            ステップ番号: 3,
            承認者名: '山田役員',
            承認者役職: '役員',
            期限日時: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
            承認状態: '未承認'
          });
        } else if (routeId === '2') { // 緊急承認フロー
          sampleSteps[0] = {
            ...sampleSteps[0],
            承認者名: '山田役員',
            承認者役職: '役員',
            期限日時: new Date(Date.now() + 1 * 24 * 60 * 60 * 1000).toISOString()
          };
        }

        renderApprovalSteps(sampleSteps);
      }
    } catch (error) {
      console.error('承認フロー情報の取得に失敗しました:', error);
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      // 申請書類の初期データを設定
      const applications = tables[APPLICATION_TABLE]?.records || [];
      const applicationSelect = container.querySelector("#select-application");

      // 既存のオプションをクリア（最初のプレースホルダーは残す）
      while (applicationSelect.children.length > 1) {
        applicationSelect.removeChild(applicationSelect.lastChild);
      }

      // 申請書類のオプションを追加
      applications.forEach(app => {
        const option = document.createElement('option');
        option.value = app.id;
        option.textContent = `${app.申請種別} - ${app.申請タイトル} (${app.申請者ID})`;
        applicationSelect.appendChild(option);
      });

    } catch (error) {
      console.error('初期化処理でエラーが発生しました:', error);
    }
  }

  // イベントリスナーの設定
  container.querySelector("#select-application").addEventListener("change", (e) => {
    handleApplicationSelect(e.target.value);
  });

  container.querySelector("#select-new-route").addEventListener("change", (e) => {
    handleNewRouteSelect(e.target.value);
  });

  // 承認者変更ボタン
  container.querySelector("#btn-change-approver").addEventListener("click", () => {
    alert("承認者変更機能は別画面で実装予定です");
  });

  // 変更内容確認ボタン
  container.querySelector("#btn-confirm").addEventListener("click", () => {
    if (!currentApplicationId) {
      alert("申請書類を選択してください");
      return;
    }

    const newRouteId = container.querySelector("#select-new-route").value;
    const reason = container.querySelector("#textarea-reason").value;

    if (!newRouteId) {
      alert("新しい処理ルートを選択してください");
      return;
    }

    if (!reason.trim()) {
      alert("変更理由を入力してください");
      return;
    }

    const confirmMessage = `
処理ルート変更内容:
- 申請書類: ${container.querySelector("#select-application option:checked").textContent}
- 新しいルート: ${container.querySelector("#select-new-route option:checked").textContent}
- 変更理由: ${reason}

この内容で変更を実行しますか？`;

    if (confirm(confirmMessage)) {
      alert("変更内容を確認しました。「ルート更新」ボタンで実行してください。");
    }
  });

  // ルート更新ボタン
  container.querySelector("#btn-execute").addEventListener("click", async () => {
    if (!currentApplicationId) {
      alert("申請書類を選択してください");
      return;
    }

    const newRouteId = container.querySelector("#select-new-route").value;
    const reason = container.querySelector("#textarea-reason").value;

    if (!newRouteId || !reason.trim()) {
      alert("新しい処理ルートと変更理由を入力してください");
      return;
    }

    try {
      // 処理ルートを更新
      if (currentRouteData) {
        const updated = await window.aivicApi.update(PROCESSING_ROUTE_TABLE, currentRouteData.id, {
          承認フロー定義ID: newRouteId,
          現在ステップ番号: 1,
          処理状況: '承認待ち',
          更新日時: new Date().toISOString(),
          備考: `ルート変更: ${reason}`
        });

        if (updated) {
          alert("処理ルートを更新しました");
          // 画面遷移
          window.showScreen("scr-1779422546501");
        } else {
          alert("処理ルートの更新に失敗しました");
        }
      } else {
        alert("現在の処理ルートが見つかりません");
      }
    } catch (error) {
      console.error('処理ルート更新エラー:', error);
      alert("処理ルートの更新中にエラーが発生しました");
    }
  });

  // 通知送信ボタン
  container.querySelector("#btn-notify").addEventListener("click", async () => {
    const notificationMessage = container.querySelector("#textarea-notification").value;
    const notifyApplicant = container.querySelector("#notify-applicant").checked;
    const notifyCurrentApprover = container.querySelector("#notify-current-approver").checked;
    const notifyNewApprover = container.querySelector("#notify-new-approver").checked;
    const notifyManager = container.querySelector("#notify-manager").checked;

    if (!notificationMessage.trim()) {
      alert("通知メッセージを入力してください");
      return;
    }

    if (!notifyApplicant && !notifyCurrentApprover && !notifyNewApprover && !notifyManager) {
      alert("通知対象者を選択してください");
      return;
    }

    try {
      // 通知履歴に記録（サンプル実装）
      const notificationData = {
        申請書類ID: currentApplicationId,
        通知種別: '処理ルート変更',
        通知タイトル: '処理ルート変更のお知らせ',
        通知内容: notificationMessage,
        送信方法: 'システム内通知',
        送信状態: '送信完了',
        送信日時: new Date().toISOString(),
        既読フラグ: false,
        再送回数: 0,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者ID: 'current-user'
      };

      // 通知対象者ごとに通知を送信
      const targets = [];
      if (notifyApplicant) targets.push('申請者');
      if (notifyCurrentApprover) targets.push('現在の承認者');
      if (notifyNewApprover) targets.push('新しい承認者');
      if (notifyManager) targets.push('管理者');

      alert(`以下の対象者に通知を送信しました:\n${targets.join(', ')}`);
    } catch (error) {
      console.error('通知送信エラー:', error);
      alert("通知の送信中にエラーが発生しました");
    }
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    if (confirm("入力内容が失われますが、よろしいですか？")) {
      // フォームをリセット
      container.querySelector("#select-application").value = "";
      container.querySelector("#select-new-route").value = "";
      container.querySelector("#textarea-reason").value = "";
      container.querySelector("#textarea-notification").value = "";
      container.querySelector("#input-status").value = "";
      container.querySelector("#current-route").textContent = "申請書類を選択してください";

      // チェックボックスをリセット
      container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);

      renderApprovalSteps([]);
      currentApplicationId = null;
      currentRouteData = null;
    }
  });

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  // 現在の日付を申請日付のデフォルトに設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#application-date').value = today;

  // ファイルアップロード機能
  const fileInput = container.querySelector('#file-input');
  const fileSelectBtn = container.querySelector('#file-select-btn');
  const fileUploadArea = container.querySelector('#file-upload-area');
  const fileList = container.querySelector('#file-list');
  let selectedFiles = [];

  fileSelectBtn.addEventListener('click', () => {
    fileInput.click();
  });

  fileInput.addEventListener('change', (e) => {
    handleFiles(e.target.files);
  });

  // ドラッグ&ドロップ
  fileUploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    fileUploadArea.style.borderColor = 'var(--primary)';
    fileUploadArea.style.background = 'rgba(255,255,255,0.05)';
  });

  fileUploadArea.addEventListener('dragleave', (e) => {
    e.preventDefault();
    fileUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    fileUploadArea.style.background = 'rgba(0,0,0,0.1)';
  });

  fileUploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    fileUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    fileUploadArea.style.background = 'rgba(0,0,0,0.1)';
    handleFiles(e.dataTransfer.files);
  });

  function handleFiles(files) {
    selectedFiles = Array.from(files);
    renderFileList();
  }

  function renderFileList() {
    if (selectedFiles.length === 0) {
      fileList.innerHTML = '';
      return;
    }

    fileList.innerHTML = selectedFiles.map((file, index) => `
      <div style="display: flex; justify-content: space-between; align-items: center; padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,0.1);">
        <span style="color: var(--text); font-size: 12px;">${file.name} (${(file.size / 1024).toFixed(1)}KB)</span>
        <button type="button" class="remove-file-btn" data-index="${index}" 
                style="background: none; border: none; color: var(--text-muted); font-size: 12px; cursor: pointer;">
          削除
        </button>
      </div>
    `).join('');
  }

  // ファイル削除
  container.addEventListener('click', (e) => {
    const removeBtn = e.target.closest('.remove-file-btn');
    if (removeBtn) {
      const index = parseInt(removeBtn.dataset.index);
      selectedFiles.splice(index, 1);
      renderFileList();
    }
  });

  // 文書種別選択時の承認フロー自動設定
  container.querySelector('#document-type').addEventListener('change', (e) => {
    const approvalFlowSelect = container.querySelector('#approval-flow');
    const docType = e.target.value;

    // 文書種別に応じて推奨承認フローを設定
    if (docType === 'vacation') {
      approvalFlowSelect.value = 'standard';
    } else if (docType === 'expense') {
      approvalFlowSelect.value = 'department';
    } else if (docType === 'proposal') {
      approvalFlowSelect.value = 'executive';
    }
  });

  // 書類アップロードボタン
  container.querySelector('#btn-upload').addEventListener('click', () => {
    window.showScreen("scr-1779422207222");
  });

  // 下書き保存
  container.querySelector('#btn-draft').addEventListener('click', async () => {
    const formData = collectFormData();
    formData.承認状態 = '下書き';

    try {
      const saved = await window.aivicApi.save(1, formData); // 申請書類テーブル
      if (saved) {
        alert('下書きを保存しました');
      } else {
        alert('保存に失敗しました');
      }
    } catch (error) {
      console.error('下書き保存エラー:', error);
      alert('保存中にエラーが発生しました');
    }
  });

  // 申請提出
  container.querySelector('#btn-submit').addEventListener('click', async () => {
    const form = container.querySelector('#application-form');
    if (!form.checkValidity()) {
      form.reportValidity();
      return;
    }

    const formData = collectFormData();
    formData.承認状態 = '申請中';
    formData.承認段階 = 1;

    try {
      const saved = await window.aivicApi.save(1, formData); // 申請書類テーブル
      if (saved) {
        alert('申請を提出しました');
        // フォームをクリア
        form.reset();
        selectedFiles = [];
        renderFileList();
        container.querySelector('#application-date').value = today;
      } else {
        alert('申請の提出に失敗しました');
      }
    } catch (error) {
      console.error('申請提出エラー:', error);
      alert('申請提出中にエラーが発生しました');
    }
  });

  function collectFormData() {
    const urgencyRadio = container.querySelector('input[name="urgency"]:checked');
    const subsidyCheckboxes = container.querySelectorAll('input[name="subsidy-relation"]:checked');
    const deptCheckboxes = container.querySelectorAll('input[name="related-department"]:checked');

    const urgencyMap = {
      'low': 1,
      'normal': 2,
      'high': 3,
      'urgent': 4
    };

    return {
      申請者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
      申請種別: container.querySelector('#document-type').value,
      申請タイトル: container.querySelector('#title').value,
      申請内容: container.querySelector('#content').value,
      申請金額: parseInt(container.querySelector('#amount').value) || null,
      申請開始日: container.querySelector('#application-date').value,
      緊急フラグ: urgencyRadio ? urgencyRadio.value === 'urgent' : false,
      添付ファイル有無: selectedFiles.length > 0,
      備考: container.querySelector('#reason').value,
      作成者ID: 'current-user-id',
      更新者ID: 'current-user-id'
    };
  }

  // 初期フォーカス
  container.querySelector('#title').focus();
}

function(container, apiUrl, tables) {
  let currentFile = null;
  let analysisResult = null;

  // ログ出力関数
  function addLog(message) {
    const logArea = container.querySelector('#processing-log');
    const timestamp = new Date().toLocaleTimeString();
    logArea.innerHTML += `\n[${timestamp}] ${message}`;
    logArea.scrollTop = logArea.scrollHeight;
  }

  // ファイルアップロード処理
  const uploadArea = container.querySelector('#upload-area');
  const fileInput = container.querySelector('#file-input');
  const fileInfo = container.querySelector('#file-info');

  // ドラッグ＆ドロップ
  uploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'var(--primary)';
  });

  uploadArea.addEventListener('dragleave', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
  });

  uploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFileSelect(files[0]);
    }
  });

  // ファイル選択
  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFileSelect(e.target.files[0]);
    }
  });

  // ファイル処理
  function handleFileSelect(file) {
    currentFile = file;
    fileInfo.textContent = `選択ファイル: ${file.name} (${(file.size / 1024).toFixed(1)} KB)`;
    addLog(`ファイル選択: ${file.name}`);

    // プレビュー表示
    const preview = container.querySelector('#document-preview');
    if (file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = (e) => {
        preview.innerHTML = `<img src="${e.target.result}" style="max-width: 100%; max-height: 100%; object-fit: contain;">`;
      };
      reader.readAsDataURL(file);
    } else {
      preview.innerHTML = `<div style="color: var(--text-muted);">${file.name}<br>プレビュー対応形式: 画像ファイル</div>`;
    }

    // 自動解析実行
    performAnalysis(file);
  }

  // 文書解析処理
  async function performAnalysis(file) {
    addLog('文書解析を開始...');

    // シミュレーション: 実際のOCR/AI解析の代わり
    setTimeout(() => {
      // ファイル名から文書種別を推測
      const fileName = file.name.toLowerCase();
      let docType = 'unknown';
      let confidence = 0.85;
      let subsidyRelevance = '低';

      if (fileName.includes('経費') || fileName.includes('expense')) {
        docType = '経費申請書';
        confidence = 0.92;
        subsidyRelevance = '低';
      } else if (fileName.includes('休暇') || fileName.includes('leave')) {
        docType = '休暇申請書';
        confidence = 0.88;
        subsidyRelevance = '無';
      } else if (fileName.includes('補助金') || fileName.includes('subsidy')) {
        docType = '補助金申請書';
        confidence = 0.95;
        subsidyRelevance = '高';
      } else if (fileName.includes('購買') || fileName.includes('purchase')) {
        docType = '購買申請書';
        confidence = 0.87;
        subsidyRelevance = '中';
      } else {
        docType = '経費申請書';
        confidence = 0.75;
        subsidyRelevance = '低';
      }

      analysisResult = {
        docType,
        confidence,
        subsidyRelevance,
        ocrText: `申請者: 田中太郎\n部署: 営業部\n申請日: 2024年1月15日\n件名: ${docType}\n金額: 50,000円\n用途: 業務関連費用\n承認者: 佐藤部長`,
        keywords: ['申請', '承認', '金額', '業務', '部署', docType.replace('書', '')]
      };

      // 結果表示
      container.querySelector('#detected-type').textContent = docType;
      container.querySelector('#confidence-score').textContent = `${(confidence * 100).toFixed(1)}%`;
      container.querySelector('#subsidy-relevance').textContent = subsidyRelevance;
      container.querySelector('#ocr-text').value = analysisResult.ocrText;

      // キーワード表示
      const keywordsList = container.querySelector('#keywords-list');
      keywordsList.innerHTML = analysisResult.keywords.map(kw => 
        `<span style="display: inline-block; background: var(--primary); color: #fff; padding: 2px 6px; margin: 2px; border-radius: 4px; font-size: 11px;">${kw}</span>`
      ).join('');

      // 承認フロー設定
      updateApprovalFlow(docType);

      addLog(`解析完了: ${docType} (信頼度: ${(confidence * 100).toFixed(1)}%)`);
    }, 2000);
  }

  // 承認フロー更新
  function updateApprovalFlow(docType) {
    const flowDisplay = container.querySelector('#approval-flow');
    let flowText = '';

    switch (docType) {
      case '経費申請書':
        flowText = '1. 直属上司 → 2. 部長 → 3. 経理部';
        break;
      case '休暇申請書':
        flowText = '1. 直属上司 → 2. 人事部';
        break;
      case '補助金申請書':
        flowText = '1. 部長 → 2. 事業部長 → 3. 役員 → 4. 社長';
        break;
      case '購買申請書':
        flowText = '1. 直属上司 → 2. 部長 → 3. 購買部';
        break;
      default:
        flowText = '1. 直属上司 → 2. 部長';
    }

    flowDisplay.textContent = flowText;
  }

  // 手動選択変更
  container.querySelector('#manual-type-select').addEventListener('change', (e) => {
    if (e.target.value) {
      const typeNames = {
        'expense-report': '経費申請書',
        'leave-request': '休暇申請書',
        'purchase-request': '購買申請書',
        'subsidy-application': '補助金申請書',
        'contract-approval': '契約承認申請',
        'budget-request': '予算申請書'
      };
      const selectedType = typeNames[e.target.value];
      container.querySelector('#detected-type').textContent = selectedType;
      updateApprovalFlow(selectedType);
      addLog(`手動選択: ${selectedType}`);
    } else if (analysisResult) {
      container.querySelector('#detected-type').textContent = analysisResult.docType;
      updateApprovalFlow(analysisResult.docType);
      addLog('自動判別結果に戻しました');
    }
  });

  // 判別結果確定
  container.querySelector('#btn-confirm').addEventListener('click', async () => {
    if (!currentFile || !analysisResult) {
      alert('ファイルを選択し、解析を完了してください');
      return;
    }

    const finalType = container.querySelector('#detected-type').textContent;
    const confidence = container.querySelector('#confidence-score').textContent;

    addLog(`判別結果確定: ${finalType}`);

    // 申請書類として保存
    const documentData = {
      申請種別: finalType,
      申請タイトル: `${finalType} - ${currentFile.name}`,
      申請内容: analysisResult.ocrText,
      承認状態: '申請中',
      承認段階: 1,
      緊急フラグ: false,
      添付ファイル有無: true,
      申請者ID: 'current-user-id', // 実際は認証情報から取得
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(1, documentData); // tables[1] = 申請書類
    if (saved) {
      addLog('申請書類として登録完了');
      alert('文書種別判別が完了し、申請書類として登録されました');
      window.showScreen('scr-1779422241190'); // 承認フロー進捗管理画面へ
    }
  });

  // 再判別実行
  container.querySelector('#btn-reanalyze').addEventListener('click', () => {
    if (!currentFile) {
      alert('ファイルを選択してください');
      return;
    }

    // 結果をクリア
    container.querySelector('#detected-type').textContent = '-';
    container.querySelector('#confidence-score').textContent = '-';
    container.querySelector('#subsidy-relevance').textContent = '-';
    container.querySelector('#ocr-text').value = '';
    container.querySelector('#keywords-list').innerHTML = '<div style="color: var(--text-muted); font-size: 12px;">解析中...</div>';
    container.querySelector('#approval-flow').textContent = '-';
    container.querySelector('#manual-type-select').value = '';

    addLog('再判別を開始...');
    performAnalysis(currentFile);
  });

  addLog('文書種別判別システム初期化完了');
}

function(container, apiUrl, tables) {
  let approvalSteps = [];
  let selectedUserId = null;
  let users = [];

  // ユーザーデータを取得
  async function loadUsers() {
    const userTable = tables.find(t => t.tableName === 'ユーザー');
    if (userTable) {
      users = userTable.records || [];
    } else {
      users = await window.aivicApi.list(0) || [];
    }
  }

  // 承認者一覧テーブルを再描画
  function renderApproverList() {
    const tbody = container.querySelector('#approver-tbody');
    tbody.innerHTML = approvalSteps.map((step, index) => `
      <tr data-id="${index}">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${step.stepNumber}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${step.approverName}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${step.position || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${step.required ? '必須' : '任意'}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${step.parallel ? 'あり' : 'なし'}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${step.proxyAllowed ? '許可' : '不許可'}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">
          <button class="action-btn secondary delete-step-btn" data-id="${index}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // ユーザー一覧を表示
  function renderUserList(userList = users) {
    const tbody = container.querySelector('#user-list-tbody');
    tbody.innerHTML = userList.map(user => `
      <tr data-user-id="${user.ユーザーID || user.id}">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">
          <input type="radio" name="selected-user" value="${user.ユーザーID || user.id}" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${user.ユーザー名 || user.name || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${user.所属部署 || user.department || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${user.役職 || user.position || ''}</td>
      </tr>
    `).join('');
  }

  // 初期化
  loadUsers().then(() => {
    renderUserList();
  });

  // 承認ステップ追加ボタン
  container.querySelector('#btn-add-step').addEventListener('click', () => {
    const modal = container.querySelector('#approver-modal');
    modal.style.display = 'block';
    renderUserList();
  });

  // モーダル閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    const modal = container.querySelector('#approver-modal');
    modal.style.display = 'none';
    selectedUserId = null;
  });

  // ユーザー選択
  container.querySelector('#btn-select-user').addEventListener('click', () => {
    const selectedRadio = container.querySelector('input[name="selected-user"]:checked');
    if (!selectedRadio) {
      alert('承認者を選択してください');
      return;
    }

    const userId = selectedRadio.value;
    const user = users.find(u => (u.ユーザーID || u.id) === userId);
    if (!user) return;

    const parallelApproval = container.querySelector('#parallel-approval').checked;

    const newStep = {
      stepNumber: approvalSteps.length + 1,
      approverUserId: userId,
      approverName: user.ユーザー名 || user.name || '',
      position: user.役職 || user.position || '',
      required: true,
      parallel: parallelApproval,
      proxyAllowed: false
    };

    approvalSteps.push(newStep);
    renderApproverList();

    const modal = container.querySelector('#approver-modal');
    modal.style.display = 'none';
  });

  // ユーザー検索
  container.querySelector('#user-search').addEventListener('input', (e) => {
    const keyword = e.target.value.toLowerCase();
    const filteredUsers = users.filter(user => {
      const name = (user.ユーザー名 || user.name || '').toLowerCase();
      const dept = (user.所属部署 || user.department || '').toLowerCase();
      const pos = (user.役職 || user.position || '').toLowerCase();
      return name.includes(keyword) || dept.includes(keyword) || pos.includes(keyword);
    });
    renderUserList(filteredUsers);
  });

  // ステップ削除
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-step-btn');
    if (deleteBtn) {
      const stepIndex = parseInt(deleteBtn.dataset.id);
      if (confirm('このステップを削除しますか？')) {
        approvalSteps.splice(stepIndex, 1);
        // ステップ番号を再採番
        approvalSteps.forEach((step, index) => {
          step.stepNumber = index + 1;
        });
        renderApproverList();
      }
    }
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const documentType = container.querySelector('#document-type').value;
    const flowName = container.querySelector('#flow-name').value;
    const approvalDeadline = container.querySelector('#approval-deadline').value;
    const delayNotification = container.querySelector('#delay-notification').checked;

    if (!documentType || !flowName || approvalSteps.length === 0) {
      alert('文書種別、承認フロー名、承認者を設定してください');
      return;
    }

    // 承認フロー定義テーブルのインデックスを取得
    const approvalFlowTableIndex = tables.findIndex(t => t.tableName === '承認フロー定義');
    if (approvalFlowTableIndex === -1) {
      alert('承認フロー定義テーブルが見つかりません');
      return;
    }

    try {
      // 各承認ステップを保存
      for (const step of approvalSteps) {
        const flowData = {
          文書種別ID: documentType,
          承認フロー名: flowName,
          承認ステップ番号: step.stepNumber,
          承認者ユーザーID: step.approverUserId,
          承認者役職: step.position,
          必須承認フラグ: step.required,
          並列承認フラグ: step.parallel,
          代理承認許可フラグ: step.proxyAllowed,
          承認期限日数: parseInt(approvalDeadline) || 3,
          有効開始日: new Date().toISOString(),
          備考: delayNotification ? '遅延通知設定あり' : '',
          作成者ID: 'current-user-id'
        };

        const result = await window.aivicApi.save(approvalFlowTableIndex, flowData);
        if (!result) {
          throw new Error('保存に失敗しました');
        }
      }

      alert('承認ルートを保存しました');

      // フォームをリセット
      container.querySelector('#document-type').value = '';
      container.querySelector('#flow-name').value = '';
      container.querySelector('#approval-deadline').value = '';
      container.querySelector('#delay-notification').checked = false;
      container.querySelector('#parallel-approval').checked = false;
      approvalSteps = [];
      renderApproverList();

    } catch (error) {
      console.error('保存エラー:', error);
      alert('保存に失敗しました');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    window.showScreen('scr-1779422241190'); // 承認フロー進捗管理画面
  });

  // 条件分岐設定ボタン
  container.querySelector('#btn-condition-branch').addEventListener('click', () => {
    alert('条件分岐設定機能は今後実装予定です');
  });

  // 代理承認者設定ボタン
  container.querySelector('#btn-proxy-approver').addEventListener('click', () => {
    alert('代理承認者設定機能は今後実装予定です');
  });

  // 初期描画
  renderApproverList();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#tbody-progress");
  const modal = container.querySelector("#modal-flow");

  // ユーザー名取得用のマップ
  let userMap = {};
  let docTypeMap = {};

  // 初期化時にユーザーと文書種別のマップを作成
  if (tables[0]) {
    tables[0].records.forEach(user => {
      userMap[user.id] = user.ユーザー名 || user.user_name || 'Unknown';
    });
  }
  if (tables[2]) {
    tables[2].records.forEach(docType => {
      docTypeMap[docType.id] = docType.文書種別名 || docType.document_type_name || 'Unknown';
    });
  }

  // 優先度表示用
  function getPriorityBadge(priority) {
    const colors = {
      1: { bg: 'rgba(34, 197, 94, 0.1)', color: '#22c55e', text: '低' },
      2: { bg: 'rgba(59, 130, 246, 0.1)', color: '#3b82f6', text: '通常' },
      3: { bg: 'rgba(245, 158, 11, 0.1)', color: '#f59e0b', text: '高' },
      4: { bg: 'rgba(239, 68, 68, 0.1)', color: '#ef4444', text: '緊急' }
    };
    const p = colors[priority] || colors[2];
    return `<span style="background: ${p.bg}; color: ${p.color}; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">${p.text}</span>`;
  }

  // 承認状態バッジ
  function getStatusBadge(status) {
    const colors = {
      '申請中': { bg: 'rgba(59, 130, 246, 0.1)', color: '#3b82f6' },
      '承認済': { bg: 'rgba(34, 197, 94, 0.1)', color: '#22c55e' },
      '却下': { bg: 'rgba(239, 68, 68, 0.1)', color: '#ef4444' },
      '差戻し': { bg: 'rgba(245, 158, 11, 0.1)', color: '#f59e0b' },
      '取下げ': { bg: 'rgba(156, 163, 175, 0.1)', color: '#9ca3af' }
    };
    const s = colors[status] || colors['申請中'];
    return `<span style="background: ${s.bg}; color: ${s.color}; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">${status}</span>`;
  }

  // 進捗バー生成
  function getProgressBar(currentStep, totalSteps) {
    const progress = Math.round((currentStep / totalSteps) * 100);
    return `
      <div style="width: 80px; background: rgba(255,255,255,0.1); border-radius: 4px; height: 6px; position: relative;">
        <div style="width: ${progress}%; background: var(--primary); border-radius: 4px; height: 100%;"></div>
        <span style="font-size: 10px; color: var(--text-muted); position: absolute; top: 8px; left: 0;">${currentStep}/${totalSteps}</span>
      </div>
    `;
  }

  // 遅延チェック
  function isDelayed(deadline) {
    if (!deadline) return false;
    return new Date(deadline) < new Date();
  }

  // テーブル再描画
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const applicantName = userMap[r.申請者ID] || r.申請者ID || '';
      const currentApproverName = userMap[r.現在承認者ID] || r.現在承認者ID || '-';
      const docTypeName = docTypeMap[r.文書種別ID] || r.申請種別 || '';
      const delayed = isDelayed(r.期限日時);
      const delayedClass = delayed ? 'style="background: rgba(239, 68, 68, 0.05);"' : '';

      return `
        <tr data-id="${r.id}" ${delayedClass}>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.id?.substring(0, 8) || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${docTypeName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${r.申請タイトル || ''}
            ${delayed ? '<span style="color: #ef4444; font-size: 11px; margin-left: 4px;">⚠ 遅延</span>' : ''}
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${applicantName}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${getStatusBadge(r.承認状態 || '申請中')}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${getProgressBar(r.承認段階 || 1, 3)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${currentApproverName}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${getPriorityBadge(r.優先度 || 2)}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${r.期限日時 ? new Date(r.期限日時).toLocaleDateString('ja-JP') : '-'}
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary view-flow-btn" data-id="${r.id}" style="margin-right: 4px;">フロー</button>
            <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 初期データ描画
  renderRows(tables[1]?.records || []);

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const statusFilter = container.querySelector("#filter-status").value;
    const docTypeFilter = container.querySelector("#filter-doctype").value;

    const rows = await window.aivicApi.list(1);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const matchKeyword = !keyword || 
        (r.申請タイトル && r.申請タイトル.toLowerCase().includes(keyword)) ||
        (userMap[r.申請者ID] && userMap[r.申請者ID].toLowerCase().includes(keyword));
      const matchStatus = !statusFilter || r.承認状態 === statusFilter;
      const matchDocType = !docTypeFilter || r.申請種別 === docTypeFilter;

      return matchKeyword && matchStatus && matchDocType;
    });

    renderRows(filtered);
  });

  // タブ切り替え
  container.addEventListener("click", async (e) => {
    const tabBtn = e.target.closest(".tab-btn");
    if (tabBtn) {
      // タブの見た目更新
      container.querySelectorAll(".tab-btn").forEach(btn => {
        btn.style.color = "var(--text-muted)";
        btn.style.borderBottomColor = "transparent";
      });
      tabBtn.style.color = "var(--text)";
      tabBtn.style.borderBottomColor = "var(--primary)";

      // フィルタリング
      const status = tabBtn.dataset.status;
      const rows = await window.aivicApi.list(1);
      if (!rows) return;

      const filtered = status ? rows.filter(r => r.承認状態 === status) : rows;
      renderRows(filtered);
      return;
    }

    // 承認フロー表示
    const flowBtn = e.target.closest(".view-flow-btn");
    if (flowBtn) {
      const applicationId = flowBtn.dataset.id;
      showApprovalFlow(applicationId);
      return;
    }

    // 詳細表示
    const detailBtn = e.target.closest(".view-detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1779422434952");
      return;
    }
  });

  // 承認フロー詳細表示
  async function showApprovalFlow(applicationId) {
    const flowContent = container.querySelector("#flow-content");
    const historyList = container.querySelector("#history-list");

    // 承認ステップ取得
    const steps = await window.aivicApi.list(4);
    const history = await window.aivicApi.list(5);

    if (steps) {
      const appSteps = steps.filter(s => s.申請書類ID === applicationId);
      flowContent.innerHTML = appSteps.map((step, index) => {
        const approverName = userMap[step.承認者ID] || step.承認者ID || '';
        const statusColor = step.承認状態 === '承認済' ? '#22c55e' : 
                           step.承認状態 === '否認' ? '#ef4444' : '#9ca3af';

        return `
          <div style="display: flex; align-items: center; margin-bottom: 8px; padding: 8px; background: var(--bg-main); border-radius: 6px;">
            <div style="width: 24px; height: 24px; border-radius: 50%; background: ${statusColor}; color: white; display: flex; align-items: center; justify-content: center; font-size: 12px; margin-right: 12px;">
              ${index + 1}
            </div>
            <div style="flex: 1;">
              <div style="font-size: 13px; color: var(--text); font-weight: 500;">${approverName}</div>
              <div style="font-size: 11px; color: var(--text-muted);">${step.承認状態 || '未承認'}</div>
            </div>
            <div style="font-size: 11px; color: var(--text-muted);">
              ${step.承認日時 ? new Date(step.承認日時).toLocaleDateString('ja-JP') : ''}
            </div>
          </div>
        `;
      }).join("");
    }

    // 承認履歴表示
    if (history) {
      const appHistory = history.filter(h => h.申請書類ID === applicationId);
      historyList.innerHTML = appHistory.map(h => {
        const approverName = userMap[h.承認者ID] || h.承認者ID || '';
        return `
          <div style="padding: 8px; border-left: 3px solid var(--primary); margin-bottom: 8px; background: var(--bg-main);">
            <div style="font-size: 13px; color: var(--text); font-weight: 500;">${approverName}</div>
            <div style="font-size: 12px; color: var(--text-muted); margin: 2px 0;">${h.承認結果 || ''}</div>
            <div style="font-size: 11px; color: var(--text-muted);">${h.承認日時 ? new Date(h.承認日時).toLocaleString('ja-JP') : ''}</div>
            ${h.承認コメント ? `<div style="font-size: 12px; color: var(--text); margin-top: 4px;">${h.承認コメント}</div>` : ''}
          </div>
