  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    modal.style.display = "none";
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1779422241190");
  });

  // モーダル外クリックで閉じる
  modal.addEventListener("click", (e) => {
    if (e.target === modal) {
      modal.style.display = "none";
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#stagnant-cases-tbody');
  const thresholdSlider = container.querySelector('#threshold-slider');
  const thresholdValue = container.querySelector('#threshold-value');

  // スライダー値の表示更新
  thresholdSlider.addEventListener('input', (e) => {
    thresholdValue.textContent = e.target.value;
  });

  // 滞留日数を計算する関数
  function calculateStagnantDays(createdDate) {
    const created = new Date(createdDate);
    const now = new Date();
    const diffTime = Math.abs(now - created);
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  }

  // 緊急度を表示用に変換
  function getPriorityLabel(priority) {
    const labels = { 1: '低', 2: '通常', 3: '高', 4: '緊急' };
    return labels[priority] || '通常';
  }

  // 緊急度に応じた色を取得
  function getPriorityColor(priority) {
    const colors = { 
      1: '#6b7280', 
      2: '#3b82f6', 
      3: '#f59e0b', 
      4: '#ef4444' 
    };
    return colors[priority] || '#3b82f6';
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const stagnantDays = calculateStagnantDays(r.作成日時 || new Date().toISOString());
      const priorityLabel = getPriorityLabel(r.優先度);
      const priorityColor = getPriorityColor(r.優先度);

      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px; font-size: 13px;">
            <input type="checkbox" class="row-checkbox" data-id="${r.id}" style="accent-color: var(--primary);">
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請書類ID || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請者名 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請種別 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請タイトル || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.現在承認者名 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.承認段階 || 1}次</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); font-weight: 600;">${stagnantDays}日</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; background: ${priorityColor}20; color: ${priorityColor};">${priorityLabel}</span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary view-btn" data-id="${r.id}" onclick="window.showScreen('scr-1779422434952')" style="margin-right: 4px;">詳細</button>
            <button class="action-btn secondary approve-btn" data-id="${r.id}" onclick="window.showScreen('scr-1779422407913')">承認</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ表示
  renderRows(tables[1]?.records || []);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const documentType = container.querySelector('#document-type').value;
    const assignee = container.querySelector('#assignee').value;
    const applicantName = container.querySelector('#applicant-name').value;
    const documentNumber = container.querySelector('#document-number').value;
    const threshold = parseInt(container.querySelector('#threshold-slider').value);
    const selectedSteps = Array.from(container.querySelectorAll('input[type="checkbox"][data-testid^="step-"]:checked')).map(cb => cb.value);
    const priority = container.querySelector('input[name="priority"]:checked')?.value;

    const rows = await window.aivicApi.list(1);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const stagnantDays = calculateStagnantDays(r.作成日時 || new Date().toISOString());

      // 滞留日数フィルタ
      if (stagnantDays < threshold) return false;

      // 日付範囲フィルタ
      if (startDate && new Date(r.作成日時) < new Date(startDate)) return false;
      if (endDate && new Date(r.作成日時) > new Date(endDate)) return false;

      // 文書種別フィルタ
      if (documentType && r.申請種別 !== documentType) return false;

      // 担当者フィルタ
      if (assignee && r.現在承認者名 !== assignee) return false;

      // 申請者名フィルタ
      if (applicantName && !r.申請者名?.includes(applicantName)) return false;

      // 申請書類番号フィルタ
      if (documentNumber && !r.申請書類ID?.includes(documentNumber)) return false;

      // 承認ステップフィルタ
      if (selectedSteps.length > 0 && !selectedSteps.includes(String(r.承認段階))) return false;

      // 緊急度フィルタ
      if (priority && String(r.優先度) !== priority) return false;

      return true;
    });

    renderRows(filtered);
  });

  // 条件クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#document-type').value = '';
    container.querySelector('#assignee').value = '';
    container.querySelector('#applicant-name').value = '';
    container.querySelector('#document-number').value = '';
    container.querySelector('#threshold-slider').value = '7';
    thresholdValue.textContent = '7';
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelectorAll('input[type="radio"]').forEach(rb => rb.checked = false);

    // 全データを再表示
    window.aivicApi.list(1).then(rows => {
      if (rows) renderRows(rows);
    });
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(1);
    if (!rows) return;

    const headers = ['申請書類番号', '申請者', '文書種別', '申請タイトル', '現在承認者', '承認段階', '滞留日数', '緊急度', '作成日時'];
    const csvData = [headers.join(',')];

    rows.forEach(r => {
      const stagnantDays = calculateStagnantDays(r.作成日時 || new Date().toISOString());
      const priorityLabel = getPriorityLabel(r.優先度);
      const row = [
        r.申請書類ID || '',
        r.申請者名 || '',
        r.申請種別 || '',
        r.申請タイトル || '',
        r.現在承認者名 || '',
        `${r.承認段階 || 1}次`,
        `${stagnantDays}日`,
        priorityLabel,
        r.作成日時 || ''
      ];
      csvData.push(row.map(field => `"${field}"`).join(','));
    });

    const csv = '\uFEFF' + csvData.join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'stagnant_cases.csv';
    link.click();
  });

  // 催促通知ボタン
  container.querySelector('#btn-notify').addEventListener('click', () => {
    const selectedIds = Array.from(container.querySelectorAll('.row-checkbox:checked')).map(cb => cb.dataset.id);
    if (selectedIds.length === 0) {
      alert('通知対象の案件を選択してください。');
      return;
    }

    // 催促通知処理画面に遷移
    window.showScreen('scr-1779422392638');
  });

  // 初期データ読み込み
  window.aivicApi.list(1).then(rows => {
    if (rows) renderRows(rows);
  });
}

function(container, apiUrl, tables) {
  let currentDelayedApplications = [];
  let selectedApplicationIds = new Set();

  // 緊急度レベルの表示名を取得
  function getUrgencyLabel(level) {
    const labels = { 1: '低', 2: '通常', 3: '高', 4: '緊急' };
    return labels[level] || '不明';
  }

  // 緊急度レベルの色を取得
  function getUrgencyColor(level) {
    const colors = { 1: '#6b7280', 2: '#3b82f6', 3: '#f59e0b', 4: '#ef4444' };
    return colors[level] || '#6b7280';
  }

  // 遅延日数を計算
  function calculateDelayDays(createdDate) {
    const created = new Date(createdDate);
    const now = new Date();
    const diffTime = Math.abs(now - created);
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  }

  // 統計情報を更新
  function updateStatistics(applications) {
    const total = applications.length;
    const urgent = applications.filter(app => app.優先度 === 4).length;
    const avgDelay = total > 0 ? Math.round(applications.reduce((sum, app) => sum + calculateDelayDays(app.作成日時), 0) / total) : 0;
    const todayNotifications = applications.filter(app => {
      const today = new Date().toDateString();
      return app.作成日時 && new Date(app.作成日時).toDateString() === today;
    }).length;

    container.querySelector('#stat-total').textContent = total;
    container.querySelector('#stat-urgent').textContent = urgent;
    container.querySelector('#stat-avg').textContent = avgDelay;
    container.querySelector('#stat-today').textContent = todayNotifications;
  }

  // 遅延申請一覧を描画
  function renderDelayedApplications(applications) {
    const tbody = container.querySelector('#delayed-applications-tbody');

    if (!applications || applications.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="padding: 20px; text-align: center; color: var(--text-muted);">遅延している申請はありません</td></tr>';
      updateStatistics([]);
      return;
    }

    tbody.innerHTML = applications.map(app => {
      const delayDays = calculateDelayDays(app.作成日時);
      const urgencyColor = getUrgencyColor(app.優先度);
      const urgencyLabel = getUrgencyLabel(app.優先度);

      return `
        <tr data-id="${app.id}" style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px 10px;">
            <input type="checkbox" class="row-checkbox" data-id="${app.id}" style="accent-color: var(--primary);">
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${app.申請書類ID?.slice(0, 8) || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${app.申請者名 || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${app.申請種別 || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${app.作成日時 ? new Date(app.作成日時).toLocaleDateString() : 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">ステップ ${app.承認段階 || 1}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${app.承認者名 || 'N/A'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: ${delayDays > 7 ? '#ef4444' : delayDays > 3 ? '#f59e0b' : 'var(--text)'};">${delayDays}日</td>
          <td style="padding: 6px 10px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${urgencyColor}20; color: ${urgencyColor}; border: 1px solid ${urgencyColor}40;">
              ${urgencyLabel}
            </span>
          </td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary remind-btn" data-id="${app.id}" style="font-size: 11px; padding: 4px 8px;">催促</button>
          </td>
        </tr>
      `;
    }).join('');

    updateStatistics(applications);
  }

  // 遅延申請データを取得してフィルタリング
  async function loadDelayedApplications() {
    try {
      // 申請書類と処理ルートを取得
      const applications = await window.aivicApi.list(1); // 申請書類テーブル
      const routes = await window.aivicApi.list(7); // 処理ルートテーブル
      const users = await window.aivicApi.list(0); // ユーザーテーブル

      if (!applications || !routes || !users) {
        renderDelayedApplications([]);
        return;
      }

      // 遅延している申請を抽出（承認待ち状態で3日以上経過）
      const delayedApps = applications.filter(app => {
        const route = routes.find(r => r.申請書類ID === app.id);
        if (!route || route.処理状況 === '承認済み' || route.処理状況 === '却下') return false;

        const delayDays = calculateDelayDays(app.作成日時);
        return delayDays >= 1; // 1日以上遅延
      }).map(app => {
        const route = routes.find(r => r.申請書類ID === app.id);
        const applicant = users.find(u => u.id === app.申請者ID);
        const approver = users.find(u => u.id === route?.現在承認者ID);

        return {
          ...app,
          申請者名: applicant?.ユーザー名 || 'N/A',
          承認者名: approver?.ユーザー名 || 'N/A',
          優先度: route?.優先度 || 2
        };
      });

      currentDelayedApplications = delayedApps;
      renderDelayedApplications(delayedApps);
    } catch (error) {
      console.error('遅延申請の取得に失敗しました:', error);
      renderDelayedApplications([]);
    }
  }

  // フィルタリング処理
  function applyFilters() {
    const documentType = container.querySelector('#filter-document-type').value;
    const urgency = container.querySelector('#filter-urgency').value;
    const delayDays = container.querySelector('#filter-delay').value;

    let filtered = [...currentDelayedApplications];

    if (documentType) {
      filtered = filtered.filter(app => app.申請種別 === documentType);
    }

    if (urgency) {
      filtered = filtered.filter(app => app.優先度 === parseInt(urgency));
    }

    if (delayDays) {
      const minDays = parseInt(delayDays);
      filtered = filtered.filter(app => calculateDelayDays(app.作成日時) >= minDays);
    }

    renderDelayedApplications(filtered);
  }

  // 催促通知送信処理
  async function sendReminder(applicationIds, title, content, method) {
    try {
      const notifications = [];

      for (const appId of applicationIds) {
        const app = currentDelayedApplications.find(a => a.id === appId);
        if (!app) continue;

        const notification = {
          申請書類ID: appId,
          通知対象ユーザーID: app.現在承認者ID,
          通知種別: '催促通知',
          通知タイトル: title,
          通知内容: content,
          送信方法: method,
          送信状態: '送信完了',
          送信日時: new Date().toISOString(),
          既読フラグ: false,
          再送回数: 0,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString(),
          作成者ID: 'current-user-id'
        };

        const saved = await window.aivicApi.save(5, notification); // 通知履歴テーブル
        if (saved) {
          notifications.push(saved);
        }
      }

      if (notifications.length > 0) {
        alert(`${notifications.length}件の催促通知を送信しました。`);
        await loadDelayedApplications(); // データを再読み込み
      } else {
        alert('催促通知の送信に失敗しました。');
      }
    } catch (error) {
      console.error('催促通知送信エラー:', error);
      alert('催促通知の送信中にエラーが発生しました。');
    }
  }

  // CSVエクスポート処理
  function exportToCSV() {
    const headers = ['申請書類番号', '申請者', '文書種別', '申請日', '承認ステップ', '承認者', '遅延日数', '緊急度'];
    const csvContent = [
      '\uFEFF' + headers.join(','),
      ...currentDelayedApplications.map(app => [
        app.申請書類ID?.slice(0, 8) || '',
        app.申請者名 || '',
        app.申請種別 || '',
        app.作成日時 ? new Date(app.作成日時).toLocaleDateString() : '',
        `ステップ ${app.承認段階 || 1}`,
        app.承認者名 || '',
        `${calculateDelayDays(app.作成日時)}日`,
        getUrgencyLabel(app.優先度)
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `遅延申請一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedApplicationIds.add(cb.dataset.id);
      } else {
        selectedApplicationIds.delete(cb.dataset.id);
      }
    });
  });

  // 一括催促ボタン
  container.querySelector('#btn-bulk-remind').addEventListener('click', () => {
    const selectedIds = Array.from(container.querySelectorAll('.row-checkbox:checked')).map(cb => cb.dataset.id);
    if (selectedIds.length === 0) {
      alert('催促する申請を選択してください。');
      return;
    }

    selectedApplicationIds = new Set(selectedIds);
    container.querySelector('#remind-modal').style.display = 'block';
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-csv-export').addEventListener('click', exportToCSV);

  // モーダル関連
  container.querySelector('#btn-cancel-remind').addEventListener('click', () => {
    container.querySelector('#remind-modal').style.display = 'none';
    selectedApplicationIds.clear();
  });

  container.querySelector('#btn-send-remind').addEventListener('click', async () => {
    const title = container.querySelector('#notification-title').value;
    const content = container.querySelector('#notification-content').value;
    const method = container.querySelector('#notification-method').value;

    if (!title || !content) {
      alert('通知タイトルと内容を入力してください。');
      return;
    }

    await sendReminder(Array.from(selectedApplicationIds), title, content, method);
    container.querySelector('#remind-modal').style.display = 'none';
    selectedApplicationIds.clear();
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 個別催促ボタン
    const remindBtn = e.target.closest('.remind-btn');
    if (remindBtn) {
      selectedApplicationIds = new Set([remindBtn.dataset.id]);
      container.querySelector('#remind-modal').style.display = 'block';
      return;
    }

    // 行チェックボックス
    const checkbox = e.target.closest('.row-checkbox');
    if (checkbox) {
      if (checkbox.checked) {
        selectedApplicationIds.add(checkbox.dataset.id);
      } else {
        selectedApplicationIds.delete(checkbox.dataset.id);
      }
    }
  });

  // 初期データ読み込み
  loadDelayedApplications();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#notification-tbody");
  const unreadCountEl = container.querySelector("#unread-count");

  // 緊急度アイコンを取得
  function getUrgencyIcon(priority) {
    switch(priority) {
      case 4: return '<span style="color: #ff4444; font-weight: bold;">🚨</span>';
      case 3: return '<span style="color: #ff8800; font-weight: bold;">⚠️</span>';
      case 2: return '<span style="color: #4488ff;">📋</span>';
      case 1: return '<span style="color: #888888;">📄</span>';
      default: return '<span style="color: #888888;">📄</span>';
    }
  }

  // 期限チェック
  function getDeadlineStatus(deadline) {
    if (!deadline) return '';
    const now = new Date();
    const deadlineDate = new Date(deadline);
    const diffHours = (deadlineDate - now) / (1000 * 60 * 60);

    if (diffHours < 0) {
      return '<span style="color: #ff4444; font-weight: bold;">期限超過</span>';
    } else if (diffHours < 24) {
      return '<span style="color: #ff8800; font-weight: bold;">本日期限</span>';
    } else if (diffHours < 48) {
      return '<span style="color: #ffaa00;">明日期限</span>';
    }
    return '';
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return `${date.getMonth()+1}/${date.getDate()} ${date.getHours().toString().padStart(2,'0')}:${date.getMinutes().toString().padStart(2,'0')}`;
  }

  // 通知データを結合して表示用データを作成
  function createNotificationData() {
    const notifications = tables[5]?.records || []; // 通知履歴
    const applications = tables[1]?.records || []; // 申請書類
    const users = tables[0]?.records || []; // ユーザー
    const routes = tables[7]?.records || []; // 処理ルート

    return notifications
      .filter(n => n.通知種別 === '承認依頼' && n.通知対象ユーザーID)
      .map(notification => {
        const application = applications.find(a => a.申請書類ID === notification.申請書類ID);
        const applicant = users.find(u => u.ユーザーID === application?.申請者ID);
        const route = routes.find(r => r.申請書類ID === notification.申請書類ID);

        return {
          id: notification.通知履歴ID,
          既読フラグ: notification.既読フラグ,
          送信日時: notification.送信日時,
          申請タイトル: application?.申請タイトル || '',
          申請種別: application?.申請種別 || '',
          申請者名: applicant?.ユーザー名 || '',
          優先度: route?.優先度 || 2,
          期限日時: route?.期限日時,
          申請書類ID: application?.申請書類ID,
          承認状態: application?.承認状態 || '申請中'
        };
      })
      .sort((a, b) => new Date(b.送信日時) - new Date(a.送信日時));
  }

  // テーブル再描画
  function renderRows(rows) {
    const unreadCount = rows.filter(r => !r.既読フラグ).length;
    unreadCountEl.textContent = unreadCount;

    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}" style="border-bottom: 1px solid var(--border); ${!row.既読フラグ ? 'background: rgba(255,255,255,0.02);' : ''}">
        <td style="padding: 8px 10px; font-size: 13px; color: var(--text);">
          ${!row.既読フラグ ? '<span style="color: var(--primary); font-weight: bold;">未読</span>' : '<span style="color: var(--text-muted);">既読</span>'}
        </td>
        <td style="padding: 8px 10px; font-size: 13px; text-align: center;">
          ${getUrgencyIcon(row.優先度)}
        </td>
        <td style="padding: 8px 10px; font-size: 13px; color: var(--text);">
          ${formatDateTime(row.送信日時)}
        </td>
        <td style="padding: 8px 10px; font-size: 13px; color: var(--text);">
          <div style="font-weight: 500;">${row.申請タイトル}</div>
          <div style="font-size: 11px; color: var(--text-muted);">${row.申請種別}</div>
        </td>
        <td style="padding: 8px 10px; font-size: 13px; color: var(--text);">
          ${row.申請者名}
        </td>
        <td style="padding: 8px 10px; font-size: 13px; color: var(--text);">
          <div>${formatDateTime(row.期限日時)}</div>
          <div style="font-size: 11px;">${getDeadlineStatus(row.期限日時)}</div>
        </td>
        <td style="padding: 8px 10px; font-size: 13px;">
          <button class="action-btn" data-testid="detail-button" onclick="window.showScreen('scr-1779422434952')" style="padding: 4px 8px; font-size: 11px; margin-right: 4px;">
            案件詳細
          </button>
          ${!row.既読フラグ ? `<button class="action-btn secondary mark-read-btn" data-id="${row.id}" style="padding: 4px 8px; font-size: 11px;">既読</button>` : ''}
        </td>
      </tr>
    `).join('');
  }

  // フィルタリング処理
  function applyFilters() {
    const allData = createNotificationData();
    const urgencyFilter = container.querySelector("#filter-urgency").value;
    const documentTypeFilter = container.querySelector("#filter-document-type").value;
    const applicantFilter = container.querySelector("#filter-applicant").value.toLowerCase();
    const deadlineFilter = container.querySelector("#filter-deadline").value;

    let filtered = allData;

    if (urgencyFilter) {
      filtered = filtered.filter(r => r.優先度.toString() === urgencyFilter);
    }

    if (documentTypeFilter) {
      filtered = filtered.filter(r => r.申請種別 === documentTypeFilter);
    }

    if (applicantFilter) {
      filtered = filtered.filter(r => r.申請者名.toLowerCase().includes(applicantFilter));
    }

    if (deadlineFilter) {
      const now = new Date();
      filtered = filtered.filter(r => {
        if (!r.期限日時) return false;
        const deadline = new Date(r.期限日時);
        const diffHours = (deadline - now) / (1000 * 60 * 60);

        switch(deadlineFilter) {
          case 'overdue': return diffHours < 0;
          case 'today': return diffHours >= 0 && diffHours < 24;
          case 'tomorrow': return diffHours >= 24 && diffHours < 48;
          case 'week': return diffHours >= 0 && diffHours < 168;
          default: return true;
        }
      });
    }

    renderRows(filtered);
  }

  // 初期データ表示
  renderRows(createNotificationData());

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  // 更新ボタン
  container.querySelector("#btn-refresh").addEventListener("click", async () => {
    try {
      const notifications = await window.aivicApi.list(5);
      const applications = await window.aivicApi.list(1);
      const users = await window.aivicApi.list(0);
      const routes = await window.aivicApi.list(7);

      if (notifications && applications && users && routes) {
        tables[5].records = notifications;
        tables[1].records = applications;
        tables[0].records = users;
        tables[7].records = routes;
        applyFilters();
      }
    } catch (error) {
      console.error('データ更新エラー:', error);
    }
  });

  // 既読マーク
  container.addEventListener("click", async (e) => {
    const markReadBtn = e.target.closest(".mark-read-btn");
    if (markReadBtn) {
      const id = markReadBtn.dataset.id;
      const updated = await window.aivicApi.update(5, id, { 既読フラグ: true, 既読日時: new Date().toISOString() });
      if (updated) {
        applyFilters();
      }
    }
  });
}

function(container, apiUrl, tables) {
  // 申請書類データの表示
  function displayApplicationData() {
    const applications = tables[0]?.records || [];
    const users = tables[1]?.records || [];
    const documentTypes = tables[2]?.records || [];

    if (applications.length > 0) {
      const app = applications[0]; // 最初の申請書類を表示
      const applicant = users.find(u => u.id === app.申請者ID) || {};
      const docType = documentTypes.find(d => d.id === app.申請種別) || {};

      // 基本情報の表示
      container.querySelector("#application-id").textContent = app.id?.substring(0, 8) || "-";
      container.querySelector("#application-date").textContent = app.作成日時 ? new Date(app.作成日時).toLocaleString('ja-JP') : "-";
      container.querySelector("#applicant-name").textContent = applicant.ユーザー名 || "-";
      container.querySelector("#applicant-dept").textContent = applicant.所属部署 || "-";
      container.querySelector("#document-type").textContent = docType.文書種別名 || app.申請種別 || "-";

      // 承認状態の表示
      const statusEl = container.querySelector("#approval-status");
      const status = app.承認状態 || "申請中";
      statusEl.textContent = status;

      // ステータス別の色分け
      if (status === "承認済") {
        statusEl.style.background = "rgba(0,200,100,0.15)";
        statusEl.style.color = "#00c864";
      } else if (status === "却下" || status === "差戻し") {
        statusEl.style.background = "rgba(255,100,100,0.15)";
        statusEl.style.color = "#ff6464";
      } else if (status === "保留") {
        statusEl.style.background = "rgba(255,200,0,0.15)";
        statusEl.style.color = "#ffc800";
      }

      // 申請内容の表示
      container.querySelector("#application-title").textContent = app.申請タイトル || "-";
      container.querySelector("#application-content").textContent = app.申請内容 || "-";
      container.querySelector("#application-amount").textContent = app.申請金額 ? `¥${app.申請金額.toLocaleString()}` : "-";
      container.querySelector("#start-date").textContent = app.申請開始日 ? new Date(app.申請開始日).toLocaleDateString('ja-JP') : "-";
      container.querySelector("#end-date").textContent = app.申請終了日 ? new Date(app.申請終了日).toLocaleDateString('ja-JP') : "-";
    }
  }

  // 承認履歴の表示
  function renderApprovalHistory() {
    const histories = tables[4]?.records || [];
    const users = tables[1]?.records || [];
    const tbody = container.querySelector("#approval-history-tbody");

    if (histories.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">承認履歴がありません</td></tr>';
      return;
    }

    tbody.innerHTML = histories.map(h => {
      const approver = users.find(u => u.id === h.承認者ID) || {};
      const result = h.承認結果 || "申請";
      let resultBadge = "";

      if (result === "承認") {
        resultBadge = `<span style="padding: 2px 6px; border-radius: 3px; font-size: 10px; background: rgba(0,200,100,0.15); color: #00c864;">${result}</span>`;
      } else if (result === "却下" || result === "差戻し") {
        resultBadge = `<span style="padding: 2px 6px; border-radius: 3px; font-size: 10px; background: rgba(255,100,100,0.15); color: #ff6464;">${result}</span>`;
      } else if (result === "保留") {
        resultBadge = `<span style="padding: 2px 6px; border-radius: 3px; font-size: 10px; background: rgba(255,200,0,0.15); color: #ffc800;">${result}</span>`;
      } else {
        resultBadge = `<span style="padding: 2px 6px; border-radius: 3px; font-size: 10px; background: rgba(0,150,255,0.15); color: #0096ff;">${result}</span>`;
      }

      return `
        <tr>
          <td style="padding: 6px 8px; color: var(--text);">${h.承認日時 ? new Date(h.承認日時).toLocaleString('ja-JP') : "-"}</td>
          <td style="padding: 6px 8px; color: var(--text);">${approver.ユーザー名 || "-"}</td>
          <td style="padding: 6px 8px;">${resultBadge}</td>
          <td style="padding: 6px 8px; color: var(--text-muted);">${h.承認コメント || "-"}</td>
        </tr>
      `;
    }).join("");
  }

  // 初期データの表示
  displayApplicationData();
  renderApprovalHistory();

  // 戻るボタンのイベント
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1779422369173");
  });

  // 承認判断ボタンのイベント
  container.querySelector("#btn-approval").addEventListener("click", () => {
    window.showScreen("scr-1779422452973");
  });

  // 添付ファイルのプレビュー・ダウンロードボタン
  container.addEventListener("click", (e) => {
    if (e.target.textContent === "プレビュー") {
      alert("ファイルプレビュー機能は実装中です");
    } else if (e.target.textContent === "ダウンロード") {
      alert("ファイルダウンロード機能は実装中です");
    }
  });

  // 承認フロー進捗の更新（現在の承認ステップに基づく）
  function updateApprovalFlow() {
    const applications = tables[0]?.records || [];
    if (applications.length > 0) {
      const app = applications[0];
      const currentStep = app.承認段階 || 1;

      // 現在のステップをハイライト
      const flowItems = container.querySelectorAll("#approval-flow > div");
      flowItems.forEach((item, index) => {
        const stepNum = index + 1;
        const circle = item.querySelector("div > div");
        const text = item.querySelector("div:last-child");

        if (stepNum === currentStep) {
          item.style.borderColor = "var(--primary)";
          item.style.background = "rgba(255,255,255,0.02)";
          circle.style.background = "var(--primary)";
          text.style.color = "var(--text)";
        } else if (stepNum < currentStep) {
          circle.style.background = "#00c864";
          text.style.color = "var(--text-muted)";
        } else {
          circle.style.background = "var(--border)";
          text.style.color = "var(--text-muted)";
        }
      });
    }
  }

  updateApprovalFlow();
}

function(container, apiUrl, tables) {
  // 申請書類データの初期表示
  function loadApplicationData() {
    const applicationData = tables[1]?.records?.[0]; // 申請書類テーブル
    const applicantData = tables[0]?.records?.find(u => u.id === applicationData?.applicant_id); // ユーザーテーブル
    const documentType = tables[2]?.records?.find(d => d.id === applicationData?.document_type_id); // 文書種別マスタ

    if (applicationData) {
      container.querySelector('#applicant-name').textContent = applicantData?.user_name || '不明';
      container.querySelector('#applicant-dept').textContent = applicantData?.department || '不明';
      container.querySelector('#document-type').textContent = documentType?.document_type_name || '不明';
      container.querySelector('#application-date').textContent = new Date(applicationData.created_at).toLocaleString('ja-JP');
      container.querySelector('#application-amount').textContent = applicationData.application_amount ? `¥${applicationData.application_amount.toLocaleString()}` : '-';
    }
  }

  // 承認履歴の描画
  function renderApprovalHistory() {
    const historyData = tables[5]?.records || []; // 承認履歴テーブル
    const tbody = container.querySelector('[data-testid="approval-history"] tbody');

    tbody.innerHTML = historyData.map(h => {
      const approver = tables[0]?.records?.find(u => u.id === h.approver_id);
      const statusBadge = h.approval_result === '承認' ? 
        `<span style="padding: 2px 6px; background: var(--primary); color: #fff; border-radius: 3px; font-size: 10px;">承認</span>` :
        h.approval_result === '差戻し' ?
        `<span style="padding: 2px 6px; background: #ff6a00; color: #fff; border-radius: 3px; font-size: 10px;">差戻し</span>` :
        `<span style="padding: 2px 6px; background: #dc3545; color: #fff; border-radius: 3px; font-size: 10px;">却下</span>`;

      return `
        <tr>
          <td style="padding: 6px 10px;">${h.approval_order || '-'}</td>
          <td style="padding: 6px 10px;">${approver?.user_name || '不明'}</td>
          <td style="padding: 6px 10px;">${statusBadge}</td>
          <td style="padding: 6px 10px;">${new Date(h.approval_date).toLocaleString('ja-JP')}</td>
          <td style="padding: 6px 10px;">${h.approval_comment || '-'}</td>
        </tr>
      `;
    }).join('');
  }

  // 条件付き承認チェックボックスの制御
  const conditionalCheckbox = container.querySelector('#conditional-approval');
  const conditionalDetails = container.querySelector('#conditional-details');

  conditionalCheckbox.addEventListener('change', function() {
    if (this.checked) {
      conditionalDetails.style.display = 'block';
    } else {
      conditionalDetails.style.display = 'none';
      container.querySelector('#approval-condition').value = '';
    }
  });

  // 判断結果ラジオボタンの制御
  const decisionRadios = container.querySelectorAll('input[name="approval-decision"]');
  decisionRadios.forEach(radio => {
    radio.addEventListener('change', function() {
      if (this.value !== 'approve') {
        conditionalCheckbox.checked = false;
        conditionalDetails.style.display = 'none';
        container.querySelector('#approval-condition').value = '';
      }
    });
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', function() {
    window.showScreen("scr-1779422434952");
  });

  // 判断確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async function() {
    const decision = container.querySelector('input[name="approval-decision"]:checked')?.value;
    const comment = container.querySelector('#approval-comment').value.trim();
    const isConditional = container.querySelector('#conditional-approval').checked;
    const condition = container.querySelector('#approval-condition').value.trim();

    if (!decision) {
      alert('判断結果を選択してください。');
      return;
    }

    if (!comment) {
      alert('承認コメントを入力してください。');
      return;
    }

    if (isConditional && !condition) {
      alert('条件付き承認の場合は、承認条件を入力してください。');
      return;
    }

    // 承認履歴に記録
    const approvalData = {
      application_id: tables[1]?.records?.[0]?.id,
      approval_step_id: 'current-step-id', // 実際は現在のステップIDを取得
      approver_id: 'current-user-id', // 実際は現在のユーザーIDを取得
      approval_result: decision === 'approve' ? '承認' : decision === 'return' ? '差戻し' : '却下',
      approval_comment: isConditional ? `${comment}\n【条件】${condition}` : comment,
      approval_date: new Date().toISOString(),
      approval_order: (tables[5]?.records?.length || 0) + 1,
      proxy_approval_flag: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(5, approvalData); // 承認履歴テーブル
    if (saved) {
      // 申請書類の状態も更新
      const applicationId = tables[1]?.records?.[0]?.id;
      if (applicationId) {
        const newStatus = decision === 'approve' ? '承認済' : decision === 'return' ? '差戻し' : '却下';
        await window.aivicApi.update(1, applicationId, {
          approval_status: newStatus,
          updated_at: new Date().toISOString()
        });
      }

      alert('承認判断を確定しました。');
      window.showScreen("scr-1779422470870");
    }
  });

  // 初期データ読み込み
  loadApplicationData();
  renderApprovalHistory();
}

