          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            ${app.最終承認日時 ? new Date(app.最終承認日時).toLocaleString('ja-JP') : ""}
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500; 
              ${notificationStatus === '送信済' ? 'background: rgba(34, 197, 94, 0.15); color: #22c55e;' : 
                'background: rgba(156, 163, 175, 0.15); color: #9ca3af;'}">
              ${notificationStatus}
            </span>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 通知状況を取得する関数
  function getNotificationStatus(applicationId) {
    const notifications = tables[6].records.filter(n => n.申請書類ID === applicationId);
    if (notifications.length === 0) return "未送信";
    const latestNotification = notifications.sort((a, b) => new Date(b.送信日時) - new Date(a.送信日時))[0];
    return latestNotification.送信状態 === '送信完了' ? '送信済' : '送信中';
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(1).then(applications => {
    if (applications) {
      // 承認済み・却下・差戻しの申請のみ表示
      const completedApplications = applications.filter(app => 
        ['承認済', '却下', '差戻し'].includes(app.承認状態)
      );
      renderApplications(completedApplications);
    }
  });

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const applicationId = container.querySelector("#search-application-id").value;
    const status = container.querySelector("#filter-status").value;
    const docType = container.querySelector("#filter-document-type").value;

    const applications = await window.aivicApi.list(1);
    if (!applications) return;

    let filtered = applications.filter(app => 
      ['承認済', '却下', '差戻し'].includes(app.承認状態)
    );

    if (applicationId) {
      filtered = filtered.filter(app => 
        app.申請番号 && app.申請番号.includes(applicationId)
      );
    }

    if (status) {
      filtered = filtered.filter(app => app.承認状態 === status);
    }

    if (docType) {
      const docTypeRecord = tables[2].records.find(dt => dt.文書種別名 === docType);
      if (docTypeRecord) {
        filtered = filtered.filter(app => app.文書種別ID === docTypeRecord.id);
      }
    }

    renderApplications(filtered);
  });

  // 4. チェックボックス選択処理
  container.addEventListener("change", (e) => {
    if (e.target.classList.contains("app-checkbox")) {
      const appId = e.target.dataset.id;
      if (e.target.checked) {
        selectedApplications.add(appId);
      } else {
        selectedApplications.delete(appId);
      }
      updateNotificationPreview();
    }
  });

  // 5. 通知テンプレート変更処理
  container.querySelector("#notification-template").addEventListener("change", (e) => {
    updateNotificationPreview();
  });

  // 通知内容プレビュー更新
  function updateNotificationPreview() {
    const template = container.querySelector("#notification-template").value;
    const subjectInput = container.querySelector("#notification-subject");
    const contentTextarea = container.querySelector("#notification-content");

    if (selectedApplications.size === 0) {
      subjectInput.value = "";
      contentTextarea.value = "";
      return;
    }

    let subject = "";
    let content = "";

    switch (template) {
      case "approval":
        subject = "【承認完了】申請が承認されました";
        content = `申請者様

お疲れ様です。
ご提出いただいた申請について、承認が完了いたしましたのでお知らせします。

承認された申請: ${selectedApplications.size}件

今後ともよろしくお願いいたします。

ハイブリッド申請承認システム`;
        break;
      case "rejection":
        subject = "【却下通知】申請が却下されました";
        content = `申請者様

お疲れ様です。
ご提出いただいた申請について、却下となりましたのでお知らせします。

却下された申請: ${selectedApplications.size}件

詳細については承認者までお問い合わせください。

ハイブリッド申請承認システム`;
        break;
      case "return":
        subject = "【差戻し通知】申請が差戻されました";
        content = `申請者様

お疲れ様です。
ご提出いただいた申請について、差戻しとなりましたのでお知らせします。

差戻された申請: ${selectedApplications.size}件

修正後、再度ご提出ください。

ハイブリッド申請承認システム`;
        break;
    }

    subjectInput.value = subject;
    contentTextarea.value = content;
  }

  // 6. 通知送信処理
  container.querySelector("#btn-send-notification").addEventListener("click", async () => {
    if (selectedApplications.size === 0) {
      alert("通知対象の申請を選択してください。");
      return;
    }

    const emailNotify = container.querySelector("#notify-email").checked;
    const systemNotify = container.querySelector("#notify-system").checked;
    const smsNotify = container.querySelector("#notify-sms").checked;

    if (!emailNotify && !systemNotify && !smsNotify) {
      alert("通知方法を選択してください。");
      return;
    }

    const subject = container.querySelector("#notification-subject").value;
    const content = container.querySelector("#notification-content").value;

    if (!subject || !content) {
      alert("件名と通知内容を入力してください。");
      return;
    }

    if (!confirm(`${selectedApplications.size}件の申請に対して通知を送信しますか？`)) {
      return;
    }

    // 通知履歴を作成
    for (const appId of selectedApplications) {
      const application = tables[1].records.find(app => app.id === appId);
      if (!application) continue;

      const methods = [];
      if (emailNotify) methods.push("メール");
      if (systemNotify) methods.push("システム内通知");
      if (smsNotify) methods.push("SMS");

      for (const method of methods) {
        const notificationData = {
          申請書類ID: appId,
          通知対象ユーザーID: application.申請者ID,
          通知種別: application.承認状態 === '承認済' ? '承認完了' : 
                   application.承認状態 === '却下' ? '却下' : '差戻し',
          通知タイトル: subject,
          通知内容: content,
          送信方法: method,
          送信状態: '送信完了',
          送信日時: new Date().toISOString(),
          既読フラグ: false,
          再送回数: 0,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString(),
          作成者ID: 'current-user-id'
        };

        await window.aivicApi.save(6, notificationData);
      }
    }

    alert(`${selectedApplications.size}件の申請に対して通知を送信しました。`);
    selectedApplications.clear();

    // チェックボックスをクリア
    container.querySelectorAll(".app-checkbox").forEach(cb => cb.checked = false);

    // プレビューをクリア
    container.querySelector("#notification-subject").value = "";
    container.querySelector("#notification-content").value = "";

    // 一覧を再読み込み
    const applications = await window.aivicApi.list(1);
    if (applications) {
      const completedApplications = applications.filter(app => 
        ['承認済', '却下', '差戻し'].includes(app.承認状態)
      );
      renderApplications(completedApplications);
    }
  });

  // 7. プレビュー確認
  container.querySelector("#btn-preview").addEventListener("click", () => {
    if (selectedApplications.size === 0) {
      alert("通知対象の申請を選択してください。");
      return;
    }

    const subject = container.querySelector("#notification-subject").value;
    const content = container.querySelector("#notification-content").value;

    if (!subject || !content) {
      alert("件名と通知内容を入力してください。");
      return;
    }

    const previewWindow = window.open("", "_blank", "width=600,height=400");
    previewWindow.document.write(`
      <html>
        <head><title>通知プレビュー</title></head>
        <body style="font-family: sans-serif; padding: 20px;">
          <h2>通知プレビュー</h2>
          <p><strong>対象申請数:</strong> ${selectedApplications.size}件</p>
          <p><strong>件名:</strong> ${subject}</p>
          <hr>
          <div style="white-space: pre-wrap;">${content}</div>
        </body>
      </html>
    `);
  });

  // 8. 通知履歴画面への遷移
  container.querySelector("#btn-history").addEventListener("click", () => {
    window.showScreen("scr-1779422306272");
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#classification-tbody');
  const form = container.querySelector('#classification-form');
  const prioritySlider = container.querySelector('#form-priority');
  const priorityValue = container.querySelector('#priority-value');
  const conditionPreview = container.querySelector('#condition-preview');

  // 優先度スライダーの値表示更新
  prioritySlider.addEventListener('input', () => {
    priorityValue.textContent = prioritySlider.value;
    updateConditionPreview();
  });

  // フォーム入力時の条件プレビュー更新
  ['#form-name', '#form-doctype', '#form-keywords', '#form-route'].forEach(selector => {
    const element = container.querySelector(selector);
    if (element) {
      element.addEventListener('input', updateConditionPreview);
    }
  });

  container.querySelectorAll('input[name="subsidy-level"]').forEach(radio => {
    radio.addEventListener('change', updateConditionPreview);
  });

  function updateConditionPreview() {
    const name = container.querySelector('#form-name').value;
    const doctype = container.querySelector('#form-doctype').value;
    const keywords = container.querySelector('#form-keywords').value;
    const route = container.querySelector('#form-route').value;
    const priority = container.querySelector('#form-priority').value;
    const subsidyLevel = container.querySelector('input[name="subsidy-level"]:checked')?.value;

    let preview = '';
    if (name) preview += `基準名: ${name}\n`;
    if (doctype) preview += `文書種別: ${doctype}\n`;
    if (subsidyLevel) {
      const levelText = subsidyLevel === '1' ? '低' : subsidyLevel === '2' ? '中' : '高';
      preview += `補助金関連度: ${levelText}\n`;
    }
    if (keywords) preview += `キーワード: ${keywords.replace(/\n/g, ', ')}\n`;
    if (route) preview += `処理ルート: ${route}\n`;
    preview += `優先度: ${priority}`;

    conditionPreview.textContent = preview || '条件を設定すると、ここにプレビューが表示されます';
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const subsidyLevelText = r.補助金関連度レベル === 1 ? '低' : r.補助金関連度レベル === 2 ? '中' : r.補助金関連度レベル === 3 ? '高' : '';
      const statusBadge = r.有効フラグ ? 
        '<span style="background: #22c55e; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">有効</span>' :
        '<span style="background: #ef4444; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">無効</span>';

      const startDate = r.適用開始日 ? new Date(r.適用開始日).toLocaleDateString('ja-JP') : '';
      const endDate = r.適用終了日 ? new Date(r.適用終了日).toLocaleDateString('ja-JP') : '';
      const period = startDate && endDate ? `${startDate} ～ ${endDate}` : startDate ? `${startDate} ～` : endDate ? `～ ${endDate}` : '';

      return `
        <tr data-id="${r.id}" style="cursor: pointer;">
          <td>${r.分類基準名 || ''}</td>
          <td>${r.文書種別 || ''}</td>
          <td>${subsidyLevelText}</td>
          <td>${r.処理ルート || ''}</td>
          <td>
            <div style="display: flex; align-items: center; gap: 4px;">
              <div style="width: 40px; height: 4px; background: rgba(255,255,255,0.1); border-radius: 2px; overflow: hidden;">
                <div style="width: ${(r.優先度 || 5) * 10}%; height: 100%; background: var(--primary);"></div>
              </div>
              <span style="font-size: 11px; color: var(--text-muted);">${r.優先度 || 5}</span>
            </div>
          </td>
          <td>${statusBadge}</td>
          <td style="font-size: 12px;">${period}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px;">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${r.id}" style="font-size: 11px; padding: 4px 8px; margin-left: 4px;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 初期データ表示
  window.aivicApi.list(0).then(rows => {
    if (rows) renderRows(rows);
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const nameFilter = container.querySelector('#search-name').value.toLowerCase();
    const doctypeFilter = container.querySelector('#search-doctype').value;
    const statusFilter = container.querySelector('#search-status').value;

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const matchName = !nameFilter || (r.分類基準名 || '').toLowerCase().includes(nameFilter);
      const matchDoctype = !doctypeFilter || r.文書種別 === doctypeFilter;
      const matchStatus = !statusFilter || r.有効フラグ?.toString() === statusFilter;
      return matchName && matchDoctype && matchStatus;
    });

    renderRows(filtered);
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ['分類基準名', '文書種別', '補助金関連度レベル', '処理ルート', '優先度', '有効フラグ', '適用開始日', '適用終了日'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(r => [
        r.分類基準名 || '',
        r.文書種別 || '',
        r.補助金関連度レベル || '',
        r.処理ルート || '',
        r.優先度 || '',
        r.有効フラグ ? '有効' : '無効',
        r.適用開始日 || '',
        r.適用終了日 || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '分類基準設定.csv';
    link.click();
  });

  // 新規作成ボタン
  container.querySelector('#btn-new').addEventListener('click', () => {
    form.reset();
    container.querySelector('#edit-id').value = '';
    container.querySelector('#form-active').checked = true;
    prioritySlider.value = '5';
    priorityValue.textContent = '5';
    updateConditionPreview();
  });

  // フォーム送信
  form.addEventListener('submit', async (e) => {
    e.preventDefault();

    const formData = {
      分類基準名: container.querySelector('#form-name').value,
      文書種別: container.querySelector('#form-doctype').value,
      補助金関連度レベル: parseInt(container.querySelector('input[name="subsidy-level"]:checked')?.value || '1'),
      キーワード条件: container.querySelector('#form-keywords').value,
      処理ルート: container.querySelector('#form-route').value,
      優先度: parseInt(container.querySelector('#form-priority').value),
      有効フラグ: container.querySelector('#form-active').checked,
      適用開始日: container.querySelector('#form-start-date').value || null,
      適用終了日: container.querySelector('#form-end-date').value || null
    };

    const editId = container.querySelector('#edit-id').value;

    let result;
    if (editId) {
      result = await window.aivicApi.update(0, editId, formData);
    } else {
      result = await window.aivicApi.save(0, formData);
    }

    if (result) {
      form.reset();
      container.querySelector('#edit-id').value = '';
      container.querySelector('#form-active').checked = true;
      prioritySlider.value = '5';
      priorityValue.textContent = '5';
      updateConditionPreview();

      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    form.reset();
    container.querySelector('#edit-id').value = '';
    container.querySelector('#form-active').checked = true;
    prioritySlider.value = '5';
    priorityValue.textContent = '5';
    updateConditionPreview();
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    const editBtn = e.target.closest('.edit-btn');

    if (deleteBtn) {
      if (!confirm('この分類基準を削除しますか？')) return;

      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }

    if (editBtn) {
      const rows = await window.aivicApi.list(0);
      if (!rows) return;

      const record = rows.find(r => r.id === editBtn.dataset.id);
      if (!record) return;

      container.querySelector('#edit-id').value = record.id;
      container.querySelector('#form-name').value = record.分類基準名 || '';
      container.querySelector('#form-doctype').value = record.文書種別 || '';

      const subsidyRadio = container.querySelector(`input[name="subsidy-level"][value="${record.補助金関連度レベル || 1}"]`);
      if (subsidyRadio) subsidyRadio.checked = true;

      container.querySelector('#form-keywords').value = record.キーワード条件 || '';
      container.querySelector('#form-route').value = record.処理ルート || '';
      container.querySelector('#form-priority').value = record.優先度 || 5;
      priorityValue.textContent = record.優先度 || 5;
      container.querySelector('#form-active').checked = record.有効フラグ !== false;
      container.querySelector('#form-start-date').value = record.適用開始日 ? record.適用開始日.split('T')[0] : '';
      container.querySelector('#form-end-date').value = record.適用終了日 ? record.適用終了日.split('T')[0] : '';

      updateConditionPreview();
    }
  });
}

function(container, apiUrl, tables) {
  let currentRouteId = null;
  let approvalSteps = [];

  // 承認ステップ再描画関数
  function renderApprovalSteps() {
    const stepsContainer = container.querySelector('#approval-steps');
    if (approvalSteps.length === 0) {
      stepsContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted); padding: 20px;">承認ステップが設定されていません</div>';
      return;
    }

    stepsContainer.innerHTML = approvalSteps.map((step, index) => `
      <div class="approval-step" data-index="${index}" style="display: flex; align-items: center; gap: 12px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); border-radius: 6px; margin-bottom: 8px; background: rgba(0,0,0,0.1);">
        <div style="font-weight: 600; color: var(--primary); min-width: 30px;">Step ${step.stepNumber}</div>
        <div style="flex: 1;">
          <div style="font-weight: 500; color: var(--text);">${step.approverName}</div>
          <div style="font-size: 11px; color: var(--text-muted);">${step.position || ''}</div>
        </div>
        <div style="display: flex; gap: 4px;">
          <button class="action-btn secondary move-up-btn" data-index="${index}" style="padding: 4px 8px; font-size: 11px;" ${index === 0 ? 'disabled' : ''}>↑</button>
          <button class="action-btn secondary move-down-btn" data-index="${index}" style="padding: 4px 8px; font-size: 11px;" ${index === approvalSteps.length - 1 ? 'disabled' : ''}>↓</button>
          <button class="action-btn secondary delete-step-btn" data-index="${index}" style="padding: 4px 8px; font-size: 11px;">削除</button>
        </div>
      </div>
    `).join('');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // URLパラメータから処理ルートIDを取得（実際の実装では適切な方法で取得）
      const urlParams = new URLSearchParams(window.location.search);
      const routeId = urlParams.get('routeId') || (tables[7]?.records?.[0]?.id);

      if (routeId) {
        currentRouteId = routeId;
        const routes = await window.aivicApi.list(7); // 処理ルートテーブル
        const route = routes?.find(r => r.id === routeId);

        if (route) {
          container.querySelector('#route-id').value = route.id || '';
          container.querySelector('#route-name').value = route.申請書類ID || '';
          container.querySelector('#process-status').value = route.処理状況 || '';
          container.querySelector('#priority').value = route.優先度 || '';
          container.querySelector('#remarks').value = route.備考 || '';

          // 承認ステップデータを読み込み
          const steps = await window.aivicApi.list(4); // 承認ステップテーブル
          const routeSteps = steps?.filter(s => s.申請書類ID === route.申請書類ID) || [];

          approvalSteps = routeSteps.map(step => ({
            id: step.id,
            stepNumber: step.ステップ番号,
            approverId: step.承認者ID,
            approverName: `承認者${step.ステップ番号}`,
            position: '部長',
            required: step.必須フラグ
          })).sort((a, b) => a.stepNumber - b.stepNumber);

          renderApprovalSteps();
        }
      }
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 承認者追加ボタン
  container.querySelector('#btn-add-step').addEventListener('click', () => {
    const modal = container.querySelector('#approver-modal');
    const stepNumber = approvalSteps.length + 1;
    container.querySelector('#modal-step-number').value = stepNumber;
    modal.style.display = 'block';
  });

  // モーダル キャンセル
  container.querySelector('#btn-modal-cancel').addEventListener('click', () => {
    container.querySelector('#approver-modal').style.display = 'none';
  });

  // モーダル 追加
  container.querySelector('#btn-modal-add').addEventListener('click', () => {
    const approverId = container.querySelector('#modal-approver').value;
    const stepNumber = parseInt(container.querySelector('#modal-step-number').value);

    if (!approverId) {
      alert('承認者を選択してください');
      return;
    }

    const approverText = container.querySelector('#modal-approver').selectedOptions[0].text;
    const [name, position] = approverText.split('（');

    approvalSteps.push({
      id: null,
      stepNumber: stepNumber,
      approverId: approverId,
      approverName: name,
      position: position?.replace('）', '') || '',
      required: false
    });

    // ステップ番号でソート
    approvalSteps.sort((a, b) => a.stepNumber - b.stepNumber);

    renderApprovalSteps();
    container.querySelector('#approver-modal').style.display = 'none';

    // フォームリセット
    container.querySelector('#modal-approver').value = '';
    container.querySelector('#modal-step-number').value = approvalSteps.length + 1;
  });

  // 承認ステップ操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-step-btn');
    const moveUpBtn = e.target.closest('.move-up-btn');
    const moveDownBtn = e.target.closest('.move-down-btn');

    if (deleteBtn) {
      const index = parseInt(deleteBtn.dataset.index);
      if (confirm('この承認ステップを削除しますか？')) {
        approvalSteps.splice(index, 1);
        // ステップ番号を再採番
        approvalSteps.forEach((step, i) => {
          step.stepNumber = i + 1;
        });
        renderApprovalSteps();
      }
    }

    if (moveUpBtn) {
      const index = parseInt(moveUpBtn.dataset.index);
      if (index > 0) {
        [approvalSteps[index], approvalSteps[index - 1]] = [approvalSteps[index - 1], approvalSteps[index]];
        // ステップ番号を再採番
        approvalSteps.forEach((step, i) => {
          step.stepNumber = i + 1;
        });
        renderApprovalSteps();
      }
    }

    if (moveDownBtn) {
      const index = parseInt(moveDownBtn.dataset.index);
      if (index < approvalSteps.length - 1) {
        [approvalSteps[index], approvalSteps[index + 1]] = [approvalSteps[index + 1], approvalSteps[index]];
        // ステップ番号を再採番
        approvalSteps.forEach((step, i) => {
          step.stepNumber = i + 1;
        });
        renderApprovalSteps();
      }
    }
  });

  // 更新保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async () => {
    try {
      if (!currentRouteId) {
        alert('処理ルートIDが設定されていません');
        return;
      }

      // 処理ルート更新
      const routeData = {
        処理状況: container.querySelector('#process-status').value,
        優先度: parseInt(container.querySelector('#priority').value) || 2,
        備考: container.querySelector('#remarks').value,
        更新日時: new Date().toISOString(),
        更新者ID: 'current-user-id'
      };

      const updatedRoute = await window.aivicApi.update(7, currentRouteId, routeData);
      if (!updatedRoute) {
        alert('処理ルートの更新に失敗しました');
        return;
      }

      // 承認ステップの更新（既存削除→新規追加）
      const existingSteps = await window.aivicApi.list(4);
      const routeSteps = existingSteps?.filter(s => s.申請書類ID === updatedRoute.申請書類ID) || [];

      // 既存ステップを削除
      for (const step of routeSteps) {
        await window.aivicApi.delete(4, step.id);
      }

      // 新しいステップを追加
      for (const step of approvalSteps) {
        const stepData = {
          申請書類ID: updatedRoute.申請書類ID,
          承認フロー定義ID: 'flow-def-id',
          ステップ番号: step.stepNumber,
          承認者ID: step.approverId,
          承認状態: '未承認',
          必須フラグ: container.querySelector('#required-approval').checked,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString(),
          作成者ID: 'current-user-id'
        };

        await window.aivicApi.save(4, stepData);
      }

      // 遅延検知設定の更新
      const delaySettings = {
        文書種別ID: container.querySelector('#document-type').value,
        設定名: '処理ルート遅延検知',
        期限日数: parseInt(container.querySelector('#deadline-days').value) || 7,
        警告日数: parseInt(container.querySelector('#warning-days').value) || 3,
        エスカレーション日数: parseInt(container.querySelector('#escalation-days').value) || 1,
        営業日計算フラグ: true,
        有効フラグ: true,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者ID: 'current-user-id',
        更新者ID: 'current-user-id'
      };

      await window.aivicApi.save(8, delaySettings);

      alert('処理ルートを更新しました');
      window.showScreen('scr-1779422591281'); // 処理ルート設定画面に戻る

    } catch (error) {
      console.error('更新エラー:', error);
      alert('更新に失敗しました');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('変更内容が失われますが、よろしいですか？')) {
      window.showScreen('scr-1779422591281');
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentFile = null;
  let classificationHistory = [];

  // DOM要素の取得
  const uploadArea = container.querySelector('#upload-area');
  const fileInput = container.querySelector('#file-input');
  const fileInfo = container.querySelector('#file-info');
  const fileName = container.querySelector('#file-name');
  const fileSize = container.querySelector('#file-size');
  const removeFileBtn = container.querySelector('#btn-remove-file');
  const autoDetectionResult = container.querySelector('#auto-detection-result');
  const accuracyBar = container.querySelector('#accuracy-bar');
  const accuracyText = container.querySelector('#accuracy-text');
  const subsidyScoreBar = container.querySelector('#subsidy-score-bar');
  const subsidyScoreText = container.querySelector('#subsidy-score-text');
  const manualDocumentType = container.querySelector('#manual-document-type');
  const documentPreview = container.querySelector('#document-preview');
  const historyTbody = container.querySelector('#history-tbody');
  const errorMessage = container.querySelector('#error-message');
  const reDetectBtn = container.querySelector('#btn-re-detect');
  const confirmBtn = container.querySelector('#btn-confirm');
  const nextScreenBtn = container.querySelector('#btn-next-screen');
  const documentMasterBtn = container.querySelector('#btn-document-master');
  const approvalFlowBtn = container.querySelector('#btn-approval-flow');

  // 文書種別マスタデータの初期化
  const documentTypes = tables[2]?.records || [
    { id: '1', 文書種別コード: 'expense-report', 文書種別名: '経費申請書' },
    { id: '2', 文書種別コード: 'leave-request', 文書種別名: '休暇申請書' },
    { id: '3', 文書種別コード: 'business-proposal', 文書種別名: '稟議書' },
    { id: '4', 文書種別コード: 'purchase-order', 文書種別名: '購買申請書' },
    { id: '5', 文書種別コード: 'travel-request', 文書種別名: '出張申請書' },
    { id: '6', 文書種別コード: 'subsidy-application', 文書種別名: '補助金申請書' }
  ];

  // 履歴表示関数
  function renderHistory() {
    if (classificationHistory.length === 0) {
      historyTbody.innerHTML = '<tr><td colspan="3" style="padding: 12px; text-align: center; color: var(--text-muted);">履歴がありません</td></tr>';
      return;
    }

    historyTbody.innerHTML = classificationHistory.map(h => `
      <tr>
        <td style="padding: 6px 8px; color: var(--text);">${h.timestamp}</td>
        <td style="padding: 6px 8px; color: var(--text);">${h.result}</td>
        <td style="padding: 6px 8px; color: var(--text);">${h.accuracy}%</td>
      </tr>
    `).join('');
  }

  // エラーメッセージ表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // ファイル情報表示
  function displayFileInfo(file) {
    fileName.textContent = file.name;
    fileSize.textContent = `${(file.size / 1024).toFixed(1)} KB`;
    fileInfo.style.display = 'block';
    uploadArea.style.display = 'none';
  }

  // ファイル削除
  function removeFile() {
    currentFile = null;
    fileInfo.style.display = 'none';
    uploadArea.style.display = 'block';
    autoDetectionResult.textContent = 'ファイルをアップロードしてください';
    accuracyBar.style.width = '0%';
    accuracyText.textContent = '0%';
    subsidyScoreBar.style.width = '0%';
    subsidyScoreText.textContent = '0%';
    documentPreview.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding-top: 120px; font-size: 13px;">文書をアップロードするとプレビューが表示されます</div>';
    reDetectBtn.disabled = true;
    confirmBtn.disabled = true;
    nextScreenBtn.disabled = true;
    manualDocumentType.value = '';
  }

  // 文書種別判定シミュレーション
  function classifyDocument(file) {
    const fileName = file.name.toLowerCase();
    let detectedType = '';
    let accuracy = 0;
    let subsidyScore = 0;

    // ファイル名による簡易判定
    if (fileName.includes('経費') || fileName.includes('expense')) {
      detectedType = '経費申請書';
      accuracy = 85;
      subsidyScore = 20;
    } else if (fileName.includes('休暇') || fileName.includes('leave')) {
      detectedType = '休暇申請書';
      accuracy = 90;
      subsidyScore = 5;
    } else if (fileName.includes('稟議') || fileName.includes('proposal')) {
      detectedType = '稟議書';
      accuracy = 80;
      subsidyScore = 60;
    } else if (fileName.includes('購買') || fileName.includes('purchase')) {
      detectedType = '購買申請書';
      accuracy = 88;
      subsidyScore = 40;
    } else if (fileName.includes('出張') || fileName.includes('travel')) {
      detectedType = '出張申請書';
      accuracy = 92;
      subsidyScore = 15;
    } else if (fileName.includes('補助金') || fileName.includes('subsidy')) {
      detectedType = '補助金申請書';
      accuracy = 95;
      subsidyScore = 95;
    } else {
      detectedType = '稟議書';
      accuracy = 65;
      subsidyScore = 30;
    }

    // 結果表示
    autoDetectionResult.textContent = detectedType;
    accuracyBar.style.width = `${accuracy}%`;
    accuracyText.textContent = `${accuracy}%`;
    subsidyScoreBar.style.width = `${subsidyScore}%`;
    subsidyScoreText.textContent = `${subsidyScore}%`;

    // プレビュー表示（簡易）
    documentPreview.innerHTML = `
      <div style="color: var(--text); font-size: 13px; line-height: 1.5;">
        <div style="font-weight: 600; margin-bottom: 8px;">文書プレビュー: ${file.name}</div>
        <div style="color: var(--text-muted); margin-bottom: 8px;">ファイルサイズ: ${(file.size / 1024).toFixed(1)} KB</div>
        <div style="padding: 12px; background: rgba(255,255,255,0.05); border-radius: 4px;">
          <div>判定された文書種別: <strong>${detectedType}</strong></div>
          <div>判定精度: ${accuracy}%</div>
          <div>補助金関連度: ${subsidyScore}%</div>
          <div style="margin-top: 8px; font-size: 12px; color: var(--text-muted);">
            ※ 実際の文書内容解析結果がここに表示されます
          </div>
        </div>
      </div>
    `;

    // 履歴に追加
    const timestamp = new Date().toLocaleString('ja-JP');
    classificationHistory.unshift({
      timestamp,
      result: detectedType,
      accuracy
    });
    renderHistory();

    // ボタン有効化
    reDetectBtn.disabled = false;
    confirmBtn.disabled = false;

    // 対応する手動選択を設定
    const typeCode = documentTypes.find(t => t.文書種別名 === detectedType)?.文書種別コード || '';
    manualDocumentType.value = typeCode;
  }

  // ファイルアップロード処理
  function handleFileUpload(file) {
    if (!file) return;

    // ファイル形式チェック
    const allowedTypes = ['.pdf', '.doc', '.docx', '.xls', '.xlsx', '.jpg', '.jpeg', '.png'];
    const fileExt = '.' + file.name.split('.').pop().toLowerCase();

    if (!allowedTypes.includes(fileExt)) {
      showError('対応していないファイル形式です。PDF、Word、Excel、画像ファイルをアップロードしてください。');
      return;
    }

    // ファイルサイズチェック（10MB制限）
    if (file.size > 10 * 1024 * 1024) {
      showError('ファイルサイズが大きすぎます。10MB以下のファイルをアップロードしてください。');
      return;
    }

    currentFile = file;
    displayFileInfo(file);

    // 判定実行
    setTimeout(() => {
      classifyDocument(file);
    }, 500);
  }

  // イベントリスナー設定
  uploadArea.addEventListener('click', () => {
    fileInput.click();
  });

  uploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'var(--primary)';
  });

  uploadArea.addEventListener('dragleave', () => {
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
  });

  uploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFileUpload(files[0]);
    }
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFileUpload(e.target.files[0]);
    }
  });

  removeFileBtn.addEventListener('click', removeFile);

  // 手動選択変更時
  manualDocumentType.addEventListener('change', () => {
    if (manualDocumentType.value && currentFile) {
      const selectedType = documentTypes.find(t => t.文書種別コード === manualDocumentType.value);
      if (selectedType) {
        autoDetectionResult.textContent = `${selectedType.文書種別名} (手動選択)`;
        confirmBtn.disabled = false;
        nextScreenBtn.disabled = false;
      }
    }
  });

  // 再判定実行
  reDetectBtn.addEventListener('click', () => {
    if (currentFile) {
      classifyDocument(currentFile);
    }
  });

  // 判定結果確定
  confirmBtn.addEventListener('click', async () => {
    if (!currentFile) return;

    const selectedType = manualDocumentType.value || 
      documentTypes.find(t => t.文書種別名 === autoDetectionResult.textContent.replace(' (手動選択)', ''))?.文書種別コード;

    if (!selectedType) {
      showError('文書種別を選択してください。');
      return;
    }

    // 申請書類として保存
    const applicationData = {
      申請者ID: 'current-user-id', // 実際のユーザーIDを設定
      申請種別: selectedType,
      申請タイトル: currentFile.name,
      申請内容: `自動判定により${autoDetectionResult.textContent}として分類されました。`,
      承認状態: '申請中',
      承認段階: 1,
      緊急フラグ: false,
      添付ファイル有無: true,
      備考: `判定精度: ${accuracyText.textContent}, 補助金関連度: ${subsidyScoreText.textContent}`,
      作成者ID: 'current-user-id'
    };

    try {
      const saved = await window.aivicApi.save(1, applicationData);
      if (saved) {
        nextScreenBtn.disabled = false;
        showError(''); // エラーをクリア
        // 成功メッセージを表示（エラーメッセージエリアを緑色で使用）
        errorMessage.style.background = 'rgba(34, 197, 94, 0.1)';
        errorMessage.style.borderColor = 'rgba(34, 197, 94, 0.3)';
        errorMessage.style.color = '#86efac';
        errorMessage.textContent = '文書種別判定が完了しました。次の工程に進んでください。';
        errorMessage.style.display = 'block';
        setTimeout(() => {
          errorMessage.style.display = 'none';
          // 元の色に戻す
          errorMessage.style.background = 'rgba(220, 38, 38, 0.1)';
          errorMessage.style.borderColor = 'rgba(220, 38, 38, 0.3)';
          errorMessage.style.color = '#fca5a5';
        }, 3000);
      }
    } catch (error) {
      showError('保存に失敗しました。再度お試しください。');
    }
  });

  // 文書種別マスタ参照
  documentMasterBtn.addEventListener('click', () => {
    // 文書種別マスタ画面への遷移（実装されている場合）
    showError('文書種別マスタ画面は別途実装されます。');
  });

  // 承認フロー確認
  approvalFlowBtn.addEventListener('click', () => {
    if (!manualDocumentType.value) {
      showError('文書種別を選択してから承認フローを確認してください。');
      return;
    }
    // 承認フロー確認画面への遷移（実装されている場合）
    showError('承認フロー確認画面は別途実装されます。');
  });

  // 次画面遷移
  nextScreenBtn.addEventListener('click', () => {
    window.showScreen("scr-1779422575885");
  });

  // 初期表示
  renderHistory();
}

function(container, apiUrl, tables) {
  // 判定履歴テーブルの再描画関数
  function renderJudgmentHistory(rows) {
    const tbody = container.querySelector("#judgment-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${r.判定日時 || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${r.文書種別 || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${r.判定結果 === '電子化可能' ? 'rgba(34, 197, 94, 0.2)' : 'rgba(239, 68, 68, 0.2)'}; color: ${r.判定結果 === '電子化可能' ? '#22c55e' : '#ef4444'};">
            ${r.判定結果 || ""}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${r.補助金関連度 || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${r.推奨ルート || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${r.判定者 || ""}</td>
      </tr>
    `).join("");
  }

  // 初期データの描画
  renderJudgmentHistory(tables[0]?.records || []);

  // 申請書類情報の初期表示
  if (tables[1]?.records?.length > 0) {
    const doc = tables[1].records[0];
    container.querySelector("#document-id").value = doc.申請書類ID || "";
    container.querySelector("#document-type").value = doc.申請種別 || "";
    container.querySelector("#document-preview").value = doc.申請内容 || "";
    container.querySelector("#applicant-name").textContent = doc.申請者名 || "-";
    container.querySelector("#applicant-dept").textContent = doc.所属部署 || "-";
    container.querySelector("#application-date").textContent = doc.作成日時 ? new Date(doc.作成日時).toLocaleString() : "-";
  }

  // 判定実行ボタン
  container.querySelector("#btn-execute-judgment").addEventListener("click", async () => {
    const documentType = container.querySelector("#document-type").value;
    const subsidyLevel = container.querySelector("#subsidy-level").value;
    const manualOverride = container.querySelector("#manual-override").checked;

    if (!documentType) {
      alert("文書種別を選択してください");
      return;
    }

    // 判定ロジック（簡易版）
    let judgmentResult = "電子化可能";
    let recommendedRoute = "標準承認ルート";
    let reason = "文書形式が電子化に適しており、必要な情報が揃っています。";

    if (subsidyLevel === "3" || subsidyLevel === "4") {
      recommendedRoute = "高度承認ルート";
      reason += " 補助金関連度が高いため、詳細な承認プロセスを推奨します。";
    }

    if (manualOverride) {
      judgmentResult = "手動判定";
      reason = "手動オーバーライドが選択されました。";
    }

    // 判定結果の表示
    const resultDiv = container.querySelector("#judgment-result");
    resultDiv.innerHTML = `
      <div style="text-align: center; margin-bottom: 8px;">
        <span style="padding: 4px 12px; border-radius: 6px; font-size: 14px; font-weight: 600; background: ${judgmentResult === '電子化可能' ? 'rgba(34, 197, 94, 0.2)' : 'rgba(59, 130, 246, 0.2)'}; color: ${judgmentResult === '電子化可能' ? '#22c55e' : '#3b82f6'};">
          ${judgmentResult}
        </span>
      </div>
      <div style="font-size: 11px; color: var(--text-muted); text-align: center;">
        判定完了: ${new Date().toLocaleString()}
      </div>
    `;

    container.querySelector("#judgment-reason").value = reason;
    container.querySelector("#recommended-route").value = recommendedRoute;

    // 判定履歴に追加
    const newRecord = {
      判定日時: new Date().toLocaleString(),
      文書種別: container.querySelector("#document-type option:checked").textContent,
      判定結果: judgmentResult,
      補助金関連度: subsidyLevel ? `レベル${subsidyLevel}` : "",
      推奨ルート: recommendedRoute,
      判定者: "システム自動判定"
    };

    const saved = await window.aivicApi.save(0, newRecord);
    if (saved) {
      const updatedRows = await window.aivicApi.list(0);
      if (updatedRows) renderJudgmentHistory(updatedRows);
    }
  });

  // 承認フロー確認ボタン
  container.querySelector("#btn-confirm-flow").addEventListener("click", () => {
    const documentType = container.querySelector("#document-type").value;
    if (!documentType) {
      alert("文書種別を選択してください");
      return;
    }
    alert(`${container.querySelector("#document-type option:checked").textContent}の承認フローを確認します`);
  });

  // 処理ルート設定ボタン
  container.querySelector("#btn-route-setting").addEventListener("click", () => {
    window.showScreen("scr-1779422591281");
  });

  // 文書種別変更時の処理
  container.querySelector("#document-type").addEventListener("change", (e) => {
    const resultDiv = container.querySelector("#judgment-result");
    if (e.target.value) {
      resultDiv.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 12px; margin-top: 40px;">判定実行ボタンを押してください</div>';
    } else {
      resultDiv.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 12px; margin-top: 40px;">判定実行後に表示されます</div>';
    }
    container.querySelector("#judgment-reason").value = "";
    container.querySelector("#recommended-route").value = "";
  });

  // 手動オーバーライドチェック時の処理
  container.querySelector("#manual-override").addEventListener("change", (e) => {
    const subsidySelect = container.querySelector("#subsidy-level");
    if (e.target.checked) {
      subsidySelect.disabled = false;
      subsidySelect.style.opacity = "1";
    } else {
      subsidySelect.disabled = false;
      subsidySelect.style.opacity = "1";
    }
  });
}

function(container, apiUrl, tables) {
  let stepCounter = 1;
  let currentSelectTarget = null;

  // 処理ルート一覧の再描画関数
  function renderRoutes(routes) {
    const tbody = container.querySelector("#route-list-tbody");
    tbody.innerHTML = routes.map(route => `
      <tr data-id="${route.id}">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${route.処理ルート名 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${route.文書種別名 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${route.承認段数 || 1}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${route.有効フラグ ? 'var(--primary)' : 'var(--text-muted)'}; color: #fff;">
            ${route.有効フラグ ? '有効' : '無効'}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <button class="action-btn secondary edit-btn" data-id="${route.id}" style="margin-right: 4px;">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${route.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ表示
  if (tables && tables.length > 0) {
    renderRoutes(tables[0].records || []);
  }

  // 最新データ取得
  window.aivicApi.list(0).then(routes => {
    if (routes) renderRoutes(routes);
  });

  // 承認ステップ追加
  container.querySelector("#btn-add-step").addEventListener("click", () => {
    stepCounter++;
    const stepsContainer = container.querySelector("#approval-steps");
    const stepHtml = `
      <div class="approval-step" style="border: 1px solid var(--border); border-radius: 6px; padding: 12px; margin-bottom: 8px; background: var(--bg-main);">
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">
          <span style="font-size: 12px; font-weight: 600; color: var(--text);">ステップ ${stepCounter}</span>
          <button class="action-btn secondary remove-step" style="padding: 4px 8px; font-size: 11px;">削除</button>
        </div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 8px;">
          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">承認者</label>
            <select class="approver-select" style="width: 100%; padding: 6px 10px; border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 13px;">
              <option value="">選択してください</option>
              <option value="user1">田中部長</option>
              <option value="user2">佐藤課長</option>
              <option value="user3">鈴木主任</option>
            </select>
          </div>
          <div>
            <label style="display: block; font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">承認期限（日）</label>
            <input type="number" class="approval-deadline" value="3" style="width: 100%; padding: 6px 10px; border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; background: rgba(0,0,0,0.25); color: var(--text); font-size: 13px;">
          </div>
        </div>
        <div style="display: flex; gap: 16px;">
          <label style="display: flex; align-items: center; font-size: 12px; color: var(--text);">
            <input type="checkbox" class="parallel-approval" style="margin-right: 6px; accent-color: var(--primary);">
            並列承認
          </label>
          <label style="display: flex; align-items: center; font-size: 12px; color: var(--text);">
            <input type="checkbox" class="proxy-approval" style="margin-right: 6px; accent-color: var(--primary);">
            代理承認可
          </label>
        </div>
      </div>
    `;
    stepsContainer.insertAdjacentHTML("beforeend", stepHtml);
    updatePreview();
  });

  // 承認ステップ削除
  container.addEventListener("click", (e) => {
    if (e.target.classList.contains("remove-step")) {
      e.target.closest(".approval-step").remove();
      updatePreview();
    }
  });

  // プレビュー更新
  function updatePreview() {
    const steps = container.querySelectorAll(".approval-step");
    const preview = container.querySelector("#route-preview");
    let previewHtml = '<div style="padding: 8px; border: 1px solid var(--border); border-radius: 4px; background: var(--bg-main);">';

    previewHtml += '<div style="margin-bottom: 4px;">申請者</div>';

    steps.forEach((step, index) => {
      const approver = step.querySelector(".approver-select").selectedOptions[0]?.text || "未選択";
      const deadline = step.querySelector(".approval-deadline").value || "3";
      const isParallel = step.querySelector(".parallel-approval").checked;

      previewHtml += '<div style="margin-bottom: 4px;">↓</div>';
      previewHtml += `<div style="margin-bottom: 4px;">${approver}（${deadline}日以内）${isParallel ? ' [並列]' : ''}</div>`;
    });

    previewHtml += '<div style="margin-bottom: 4px;">↓</div>';
    previewHtml += '<div>承認完了</div>';
    previewHtml += '</div>';

    preview.innerHTML = previewHtml;
  }

  // 承認者選択の変更時にプレビュー更新
  container.addEventListener("change", (e) => {
    if (e.target.classList.contains("approver-select") || 
        e.target.classList.contains("approval-deadline") ||
        e.target.classList.contains("parallel-approval")) {
      updatePreview();
    }
  });

  // 承認者選択モーダル
  const modal = container.querySelector("#approver-modal");
  const closeModal = container.querySelector("#close-approver-modal");

  container.addEventListener("click", (e) => {
    if (e.target.classList.contains("approver-select")) {
      currentSelectTarget = e.target;
      modal.style.display = "block";
    }
  });

  closeModal.addEventListener("click", () => {
    modal.style.display = "none";
  });

  // 承認者選択
  container.addEventListener("click", (e) => {
    if (e.target.closest(".approver-item")) {
      const item = e.target.closest(".approver-item");
      const userId = item.dataset.userId;
      const userName = item.querySelector("div").textContent;

      if (currentSelectTarget) {
        currentSelectTarget.value = userId;
        // 選択肢を更新
        const option = currentSelectTarget.querySelector(`option[value="${userId}"]`);
        if (option) option.selected = true;
        updatePreview();
      }

      modal.style.display = "none";
    }
  });

  // 処理ルート保存
  container.querySelector("#btn-save-route").addEventListener("click", async () => {
    const routeName = container.querySelector("#input-route-name").value;
    const documentType = container.querySelector("#select-document-type").value;
    const amountCondition = container.querySelector("#input-amount-condition").value;
    const urgency = container.querySelector("#select-urgency").value;
    const delayNotification = container.querySelector("#check-delay-notification").checked;
    const escalation = container.querySelector("#check-escalation").checked;
    const warningDays = container.querySelector("#input-warning-days").value;
    const escalationDays = container.querySelector("#input-escalation-days").value;
    const isActive = container.querySelector("#check-route-active").checked;

    if (!routeName || !documentType) {
      alert("処理ルート名と文書種別は必須です");
      return;
    }

    const steps = Array.from(container.querySelectorAll(".approval-step")).map((step, index) => ({
      stepNumber: index + 1,
      approver: step.querySelector(".approver-select").value,
      deadline: step.querySelector(".approval-deadline").value,
      isParallel: step.querySelector(".parallel-approval").checked,
      allowProxy: step.querySelector(".proxy-approval").checked
    }));

    const routeData = {
      処理ルート名: routeName,
      文書種別名: documentType,
      承認段数: steps.length,
      金額条件: amountCondition ? parseInt(amountCondition) : null,
      緊急度: urgency ? parseInt(urgency) : null,
      遅延通知フラグ: delayNotification,
      エスカレーションフラグ: escalation,
      警告日数: warningDays ? parseInt(warningDays) : 1,
      エスカレーション日数: escalationDays ? parseInt(escalationDays) : 2,
      有効フラグ: isActive,
      承認ステップ: JSON.stringify(steps),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(0, routeData);
    if (saved) {
      alert("処理ルートを保存しました");
      // フォームクリア
      container.querySelector("#input-route-name").value = "";
      container.querySelector("#select-document-type").value = "";
      container.querySelector("#input-amount-condition").value = "";
      container.querySelector("#select-urgency").value = "";

      // 一覧更新
      const routes = await window.aivicApi.list(0);
      if (routes) renderRoutes(routes);
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    const editBtn = e.target.closest(".edit-btn");

    if (deleteBtn) {
      if (!confirm("この処理ルートを削除しますか？")) return;

      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const routes = await window.aivicApi.list(0);
      if (routes) renderRoutes(routes);
    }

    if (editBtn) {
      // 編集機能は簡略化（実際の実装では詳細な編集フォームを表示）
      alert("編集機能は開発中です");
    }
  });

  // 初期プレビュー表示
  updatePreview();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#document-tbody");
  const resultCount = container.querySelector("#result-count");

  // ユーザーマスタを取得（申請者・承認者名の表示用）
  let users = [];
  if (tables[0] && tables[0].tableName === "ユーザー") {
    users = tables[0].records || [];
  }

  // 申請書類データを取得
  let documents = [];
  const documentTableIndex = tables.findIndex(t => t.tableName === "申請書類");
  if (documentTableIndex >= 0) {
    documents = tables[documentTableIndex].records || [];
  }

  // ユーザー名取得関数
  function getUserName(userId) {
    const user = users.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : "不明";
  }

  // 承認状態のバッジスタイル
  function getStatusBadge(status) {
    let bgColor = "rgba(100,100,100,0.2)";
    let textColor = var("--text");

    switch(status) {
      case "申請中":
        bgColor = "rgba(255,193,7,0.2)";
        textColor = "#d0e4ff";
        break;
      case "承認済":
        bgColor = "rgba(40,167,69,0.2)";
        textColor = "#d0e4ff";
        break;
      case "却下":
        bgColor = "rgba(220,53,69,0.2)";
        textColor = "#d0e4ff";
        break;
      case "取下げ":
        bgColor = "rgba(108,117,125,0.2)";
        textColor = "#d0e4ff";
        break;
    }

    return `<span style="background: ${bgColor}; color: ${textColor}; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${status}</span>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.申請書類ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
          <a href="#" class="document-link" data-id="${r.申請書類ID}" style="color: var(--primary); text-decoration: none;">${r.申請書類ID?.substring(0,8) || ""}</a>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請種別 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請タイトル || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${getUserName(r.申請者ID)}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.作成日時 ? new Date(r.作成日時).toLocaleDateString() : ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${getStatusBadge(r.承認状態 || "")}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${getUserName(r.現在承認者ID)}</td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <button class="action-btn secondary view-btn" data-id="${r.申請書類ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">詳細</button>
        </td>
      </tr>
    `).join("");

    resultCount.textContent = `${rows.length}件`;
  }

  // 初期データ表示
  renderRows(documents);

  // 検索実行
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#search-keyword").value.toLowerCase();
    const docType = container.querySelector("#document-type").value;
    const status = container.querySelector("#approval-status").value;
    const dateFrom = container.querySelector("#date-from").value;
    const dateTo = container.querySelector("#date-to").value;
    const applicantName = container.querySelector("#applicant-name").value.toLowerCase();
    const approverName = container.querySelector("#approver-name").value.toLowerCase();
    const processRoute = container.querySelector("#process-route").value;
    const subsidyLevel = container.querySelector('input[name="subsidy-level"]:checked')?.value || "";

    try {
      const allDocuments = await window.aivicApi.list(documentTableIndex);

      const filtered = allDocuments.filter(doc => {
        // キーワード検索
        if (keyword && !JSON.stringify(doc).toLowerCase().includes(keyword)) return false;

        // 文書種別
        if (docType && doc.申請種別 !== docType) return false;

        // 承認状態
        if (status && doc.承認状態 !== status) return false;

        // 申請日範囲
        if (dateFrom && doc.作成日時) {
          const docDate = new Date(doc.作成日時).toISOString().split('T')[0];
          if (docDate < dateFrom) return false;
        }
        if (dateTo && doc.作成日時) {
          const docDate = new Date(doc.作成日時).toISOString().split('T')[0];
          if (docDate > dateTo) return false;
        }

        // 申請者名
        if (applicantName && !getUserName(doc.申請者ID).toLowerCase().includes(applicantName)) return false;

        // 承認者名
        if (approverName && !getUserName(doc.現在承認者ID).toLowerCase().includes(approverName)) return false;

        // 処理ルート（簡易実装）
        if (processRoute && doc.緊急フラグ) {
          if (processRoute !== "緊急承認ルート") return false;
        } else if (processRoute && processRoute !== "通常承認ルート" && !doc.緊急フラグ) {
          return false;
        }

        return true;
      });

      renderRows(filtered);
    } catch (error) {
      console.error("検索エラー:", error);
      renderRows([]);
    }
  });

  // 条件クリア
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#search-keyword").value = "";
    container.querySelector("#document-type").value = "";
    container.querySelector("#approval-status").value = "";
    container.querySelector("#date-from").value = "";
    container.querySelector("#date-to").value = "";
    container.querySelector("#applicant-name").value = "";
    container.querySelector("#approver-name").value = "";
    container.querySelector("#process-route").value = "";
    const subsidyRadios = container.querySelectorAll('input[name="subsidy-level"]');
    subsidyRadios.forEach(radio => radio.checked = false);
    subsidyRadios[0].checked = true; // "すべて"を選択

    renderRows(documents);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const allDocuments = await window.aivicApi.list(documentTableIndex);

      const headers = ["文書番号", "申請種別", "申請タイトル", "申請者", "申請日", "承認状態", "現在承認者"];
      const csvData = [headers.join(",")];

      allDocuments.forEach(doc => {
        const row = [
          `"${doc.申請書類ID?.substring(0,8) || ""}"`,
          `"${doc.申請種別 || ""}"`,
          `"${doc.申請タイトル || ""}"`,
          `"${getUserName(doc.申請者ID)}"`,
          `"${doc.作成日時 ? new Date(doc.作成日時).toLocaleDateString() : ""}"`,
          `"${doc.承認状態 || ""}"`,
          `"${getUserName(doc.現在承認者ID)}"`
        ];
        csvData.push(row.join(","));
      });

      const csvContent = "\uFEFF" + csvData.join("\n");
      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `電子文書検索結果_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error("エクスポートエラー:", error);
    }
  });

  // 行レベル操作（詳細表示・文書番号リンク）
  container.addEventListener("click", (e) => {
    const viewBtn = e.target.closest(".view-btn");
    const docLink = e.target.closest(".document-link");

    if (viewBtn) {
      const docId = viewBtn.dataset.id;
      // 申請書類確認画面に遷移
      window.showScreen("scr-1779422434952");
    }

    if (docLink) {
      e.preventDefault();
      const docId = docLink.dataset.id;
      // 申請書類確認画面に遷移
      window.showScreen("scr-1779422434952");
    }
  });
}
